const group = new THREE.Group();

// Materials
const concreteDark = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.9, side: THREE.DoubleSide });
const concreteMed = new THREE.MeshStandardMaterial({ color: 0x777777, roughness: 0.85, side: THREE.DoubleSide });
const concreteLight = new THREE.MeshStandardMaterial({ color: 0x999999, roughness: 0.8, side: THREE.DoubleSide });
const steelDark = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.6, metalness: 0.4, side: THREE.DoubleSide });
const steelMed = new THREE.MeshStandardMaterial({ color: 0x666666, roughness: 0.5, metalness: 0.5, side: THREE.DoubleSide });
const missileMat = new THREE.MeshStandardMaterial({ color: 0x888888, roughness: 0.4, metalness: 0.6, side: THREE.DoubleSide });
const missileNose = new THREE.MeshStandardMaterial({ color: 0x666666, roughness: 0.3, metalness: 0.7, side: THREE.DoubleSide });
const gratingMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.7, metalness: 0.3, side: THREE.DoubleSide });

// === BASE PLATFORM ===
// Wide stepped base
const basePlatform = new THREE.Mesh(
  new THREE.BoxGeometry(24, 3, 24),
  concreteMed
);
basePlatform.userData.textureId = "concrete-exposed";
basePlatform.position.y = 1.5;
group.add(basePlatform);

// Second step
const baseStep2 = new THREE.Mesh(
  new THREE.BoxGeometry(22, 2, 22),
  concreteDark
);
baseStep2.userData.textureId = "concrete-exposed";
baseStep2.position.y = 4;
group.add(baseStep2);

// === MAIN BODY - LOWER SECTION ===
// Left wing lower
const leftWingLower = new THREE.Mesh(
  new THREE.BoxGeometry(8, 25, 14),
  concreteLight
);
leftWingLower.userData.textureId = "concrete-precast";
leftWingLower.position.set(-7, 17.5, 0);
group.add(leftWingLower);

// Right wing lower
const rightWingLower = new THREE.Mesh(
  new THREE.BoxGeometry(8, 25, 14),
  concreteLight
);
rightWingLower.userData.textureId = "concrete-precast";
rightWingLower.position.set(7, 17.5, 0);
group.add(rightWingLower);

// Left wing detail insets
const leftInset1 = new THREE.Mesh(
  new THREE.BoxGeometry(1, 8, 3),
  concreteDark
);
leftInset1.userData.textureId = "concrete-smooth";
leftInset1.position.set(-3.5, 18, 3);
group.add(leftInset1);

const leftInset2 = new THREE.Mesh(
  new THREE.BoxGeometry(1, 8, 3),
  concreteDark
);
leftInset2.userData.textureId = "concrete-smooth";
leftInset2.position.set(-3.5, 18, -3);
group.add(leftInset2);

// Right wing detail insets
const rightInset1 = new THREE.Mesh(
  new THREE.BoxGeometry(1, 8, 3),
  concreteDark
);
rightInset1.userData.textureId = "concrete-smooth";
rightInset1.position.set(3.5, 18, 3);
group.add(rightInset1);

const rightInset2 = new THREE.Mesh(
  new THREE.BoxGeometry(1, 8, 3),
  concreteDark
);
rightInset2.userData.textureId = "concrete-smooth";
rightInset2.position.set(3.5, 18, -3);
group.add(rightInset2);

// Horizontal band details on wings (louvers/vents)
for (let i = 0; i < 4; i++) {
  const louverL = new THREE.Mesh(
    new THREE.BoxGeometry(0.5, 0.4, 4),
    steelDark
  );
  louverL.userData.textureId = "metal-grating";
  louverL.position.set(-10.5, 12 + i * 1.2, 4.5);
  group.add(louverL);

  const louverR = new THREE.Mesh(
    new THREE.BoxGeometry(0.5, 0.4, 4),
    steelDark
  );
  louverR.userData.textureId = "metal-grating";
  louverR.position.set(10.5, 12 + i * 1.2, 4.5);
  group.add(louverR);
}

// === CENTRAL SILO ===
// Central silo back wall
const siloBack = new THREE.Mesh(
  new THREE.BoxGeometry(10, 40, 4),
  concreteDark
);
siloBack.userData.textureId = "concrete-exposed";
siloBack.position.set(0, 25, -3);
group.add(siloBack);

// Central silo side walls (inner structure)
const siloWallL = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 40, 10),
  concreteMed
);
siloWallL.userData.textureId = "concrete-smooth";
siloWallL.position.set(-3.5, 25, 2);
group.add(siloWallL);

const siloWallR = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 40, 10),
  concreteMed
);
siloWallR.userData.textureId = "concrete-smooth";
siloWallR.position.set(3.5, 25, 2);
group.add(siloWallR);

// Vertical rail/track details along silo
const railL = new THREE.Mesh(
  new THREE.BoxGeometry(0.4, 38, 0.6),
  steelMed
);
railL.userData.textureId = "steel-panel";
railL.position.set(-2.5, 24, 5);
group.add(railL);

const railR = new THREE.Mesh(
  new THREE.BoxGeometry(0.4, 38, 0.6),
  steelMed
);
railR.userData.textureId = "steel-panel";
railR.position.set(2.5, 24, 5);
group.add(railR);

// Ladder-like details on silo walls
for (let i = 0; i < 12; i++) {
  const rung = new THREE.Mesh(
    new THREE.BoxGeometry(0.3, 0.15, 0.5),
    steelDark
  );
  rung.position.set(-2.5, 8 + i * 3, 5.3);
  group.add(rung);

  const rungR = new THREE.Mesh(
    new THREE.BoxGeometry(0.3, 0.15, 0.5),
    steelDark
  );
  rungR.position.set(2.5, 8 + i * 3, 5.3);
  group.add(rungR);
}

// === UPPER PILLARS/BUTTRESSES ===
// Tall vertical pillars that taper and support the canopy
// Front-left pillar
const pillarFL = new THREE.Mesh(
  new THREE.BoxGeometry(2.5, 50, 3),
  concreteDark
);
pillarFL.userData.textureId = "concrete-exposed";
pillarFL.position.set(-5, 30, 5);
group.add(pillarFL);

// Front-right pillar
const pillarFR = new THREE.Mesh(
  new THREE.BoxGeometry(2.5, 50, 3),
  concreteDark
);
pillarFR.userData.textureId = "concrete-exposed";
pillarFR.position.set(5, 30, 5);
group.add(pillarFR);

// Rear-left pillar
const pillarRL = new THREE.Mesh(
  new THREE.BoxGeometry(2.5, 50, 3),
  concreteDark
);
pillarRL.userData.textureId = "concrete-exposed";
pillarRL.position.set(-5, 30, -5);
group.add(pillarRL);

// Rear-right pillar
const pillarRR = new THREE.Mesh(
  new THREE.BoxGeometry(2.5, 50, 3),
  concreteDark
);
pillarRR.userData.textureId = "concrete-exposed";
pillarRR.position.set(5, 30, -5);
group.add(pillarRR);

// === UPPER WING EXTENSIONS ===
// The wings extend upward but narrower
const leftWingUpper = new THREE.Mesh(
  new THREE.BoxGeometry(5, 20, 10),
  concreteLight
);
leftWingUpper.userData.textureId = "concrete-precast";
leftWingUpper.position.set(-8, 35, 0);
group.add(leftWingUpper);

const rightWingUpper = new THREE.Mesh(
  new THREE.BoxGeometry(5, 20, 10),
  concreteLight
);
rightWingUpper.userData.textureId = "concrete-precast";
rightWingUpper.position.set(8, 35, 0);
group.add(rightWingUpper);

// === OVERHANGING CANOPY / CAP ===
// The distinctive flared top seen in the front elevation
// Main canopy platform
const canopyShape = new THREE.Shape();
canopyShape.moveTo(-11, -8);
canopyShape.lineTo(11, -8);
canopyShape.lineTo(8, 8);
canopyShape.lineTo(-8, 8);
canopyShape.closePath();

const canopyGeo = new THREE.ExtrudeGeometry(canopyShape, { depth: 3, bevelEnabled: false });
const canopy = new THREE.Mesh(canopyGeo, concreteDark);
canopy.rotation.x = -Math.PI / 2;
canopy.position.set(0, 56, 8);
group.add(canopy);

// Canopy top slab
const canopyTop = new THREE.Mesh(
  new THREE.BoxGeometry(22, 2, 18),
  steelDark
);
canopyTop.userData.textureId = "steel-panel";
canopyTop.position.set(0, 58, 0);
group.add(canopyTop);

// Canopy underside detail beams
const canopyBeam1 = new THREE.Mesh(
  new THREE.BoxGeometry(20, 1, 1.5),
  concreteDark
);
canopyBeam1.userData.textureId = "concrete-smooth";
canopyBeam1.position.set(0, 55, 4);
group.add(canopyBeam1);

const canopyBeam2 = new THREE.Mesh(
  new THREE.BoxGeometry(20, 1, 1.5),
  concreteDark
);
canopyBeam2.userData.textureId = "concrete-smooth";
canopyBeam2.position.set(0, 55, -4);
group.add(canopyBeam2);

// Angled supports under canopy (buttresses)
// Front-left angled support
const supportFL = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 12, 2),
  concreteMed
);
supportFL.userData.textureId = "concrete-exposed";
supportFL.rotation.z = 0.3;
supportFL.position.set(-8, 50, 4);
group.add(supportFL);

// Front-right angled support
const supportFR = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 12, 2),
  concreteMed
);
supportFR.userData.textureId = "concrete-exposed";
supportFR.rotation.z = -0.3;
supportFR.position.set(8, 50, 4);
group.add(supportFR);

// Rear-left angled support
const supportRL = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 12, 2),
  concreteMed
);
supportRL.userData.textureId = "concrete-exposed";
supportRL.rotation.z = 0.3;
supportRL.position.set(-8, 50, -4);
group.add(supportRL);

// Rear-right angled support
const supportRR = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 12, 2),
  concreteMed
);
supportRR.userData.textureId = "concrete-exposed";
supportRR.rotation.z = -0.3;
supportRR.position.set(8, 50, -4);
group.add(supportRR);

// === THE MISSILE ===
// Main missile body (cylinder)
const missileBody = new THREE.Mesh(
  new THREE.CylinderGeometry(2, 2.2, 32, 16),
  missileMat
);
missileBody.position.set(0, 26, 2);
group.add(missileBody);

// Missile upper stage (slightly thinner)
const missileUpper = new THREE.Mesh(
  new THREE.CylinderGeometry(1.8, 2, 10, 16),
  missileMat
);
missileUpper.position.set(0, 47, 2);
group.add(missileUpper);

// Missile nose cone
const noseCone = new THREE.Mesh(
  new THREE.CylinderGeometry(0, 1.8, 8, 16),
  missileNose
);
noseCone.position.set(0, 56, 2);
group.add(noseCone);

// Missile interstage band
const interstage = new THREE.Mesh(
  new THREE.CylinderGeometry(2.3, 2.3, 1.5, 16),
  steelMed
);
interstage.position.set(0, 41, 2);
group.add(interstage);

// Missile lower interstage
const interstage2 = new THREE.Mesh(
  new THREE.CylinderGeometry(2.4, 2.4, 1, 16),
  steelDark
);
interstage2.position.set(0, 20, 2);
group.add(interstage2);

// === MISSILE FINS ===
// Four fins at the base of the missile
const finMat = new THREE.MeshStandardMaterial({ color: 0x666666, roughness: 0.5, metalness: 0.5, side: THREE.DoubleSide });

for (let i = 0; i < 4; i++) {
  const finShape = new THREE.Shape();
  finShape.moveTo(0, 0);
  finShape.lineTo(2.5, 0);
  finShape.lineTo(1, 8);
  finShape.lineTo(0, 8);
  finShape.closePath();

  const finGeo = new THREE.ExtrudeGeometry(finShape, { depth: 0.3, bevelEnabled: false });
  const fin = new THREE.Mesh(finGeo, finMat);
  fin.position.set(0, 6, 2);
  fin.rotation.y = (Math.PI / 2) * i;

  // Position fins around missile
  const angle = (Math.PI / 2) * i;
  const radius = 2.2;
  fin.position.set(
    Math.cos(angle) * radius,
    6,
    2 + Math.sin(angle) * radius
  );
  fin.rotation.y = -angle;
  group.add(fin);
}

// === REAR SECTION DETAILS ===
// Rear service area / equipment blocks
const rearBlock1 = new THREE.Mesh(
  new THREE.BoxGeometry(8, 10, 3),
  concreteMed
);
rearBlock1.userData.textureId = "concrete-precast";
rearBlock1.position.set(0, 15, -6);
group.add(rearBlock1);

// Rear panels/doors
const rearDoor = new THREE.Mesh(
  new THREE.BoxGeometry(4, 6, 0.3),
  steelDark
);
rearDoor.userData.textureId = "steel-panel";
rearDoor.position.set(0, 10, -7.5);
group.add(rearDoor);

// Rear vents
for (let i = 0; i < 3; i++) {
  const ventL = new THREE.Mesh(
    new THREE.BoxGeometry(3, 0.5, 0.3),
    gratingMat
  );
  ventL.userData.textureId = "metal-grating";
  ventL.position.set(-6, 22 + i * 2, -7.1);
  group.add(ventL);

  const ventR = new THREE.Mesh(
    new THREE.BoxGeometry(3, 0.5, 0.3),
    gratingMat
  );
  ventR.userData.textureId = "metal-grating";
  ventR.position.set(6, 22 + i * 2, -7.1);
  group.add(ventR);
}

// === SIDE DETAILS ===
// Windows/openings on sides
const windowMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.2, metalness: 0.3, side: THREE.DoubleSide });

// Left side windows
const winL1 = new THREE.Mesh(
  new THREE.BoxGeometry(0.3, 3, 2),
  windowMat
);
winL1.position.set(-10.6, 30, 0);
group.add(winL1);

const winL2 = new THREE.Mesh(
  new THREE.BoxGeometry(0.3, 3, 2),
  windowMat
);
winL2.position.set(-10.6, 36, 0);
group.add(winL2);

// Right side windows
const winR1 = new THREE.Mesh(
  new THREE.BoxGeometry(0.3, 3, 2),
  windowMat
);
winR1.position.set(10.6, 30, 0);
group.add(winR1);

const winR2 = new THREE.Mesh(
  new THREE.BoxGeometry(0.3, 3, 2),
  windowMat
);
winR2.position.set(10.6, 36, 0);
group.add(winR2);

// === FRONT DECORATIVE ELEMENTS ===
// Vertical ribs on front face
for (let i = -2; i <= 2; i++) {
  if (i === 0) continue;
  const rib = new THREE.Mesh(
    new THREE.BoxGeometry(0.4, 30, 0.4),
    steelDark
  );
  rib.userData.textureId = "steel-panel";
  rib.position.set(i * 1.5, 22, 7.2);
  group.add(rib);
}

// === CORNER BUTTRESSES ===
// Angled corner pieces at base for the scary/brutalist look
const buttressGeoL = new THREE.BoxGeometry(3, 15, 3);
const buttressL = new THREE.Mesh(buttressGeoL, concreteDark);
buttressL.userData.textureId = "concrete-exposed";
buttressL.position.set(-10, 12.5, 6);
buttressL.rotation.y = Math.PI / 4;
group.add(buttressL);

const buttressR = new THREE.Mesh(buttressGeoL.clone(), concreteDark);
buttressR.userData.textureId = "concrete-exposed";
buttressR.position.set(10, 12.5, 6);
buttressR.rotation.y = -Math.PI / 4;
group.add(buttressR);

const buttressLR = new THREE.Mesh(buttressGeoL.clone(), concreteDark);
buttressLR.userData.textureId = "concrete-exposed";
buttressLR.position.set(-10, 12.5, -6);
buttressLR.rotation.y = -Math.PI / 4;
group.add(buttressLR);

const buttressRR = new THREE.Mesh(buttressGeoL.clone(), concreteDark);
buttressRR.userData.textureId = "concrete-exposed";
buttressRR.position.set(10, 12.5, -6);
buttressRR.rotation.y = Math.PI / 4;
group.add(buttressRR);

// === LAUNCH PLATFORM BASE ===
// Central floor under missile
const launchPad = new THREE.Mesh(
  new THREE.CylinderGeometry(3.5, 3.5, 1, 16),
  gratingMat
);
launchPad.userData.textureId = "metal-grating";
launchPad.position.set(0, 5.5, 2);
group.add(launchPad);

// Flame deflector shape at very base
const deflector = new THREE.Mesh(
  new THREE.BoxGeometry(6, 2, 6),
  steelDark
);
deflector.userData.textureId = "metal-grating";
deflector.position.set(0, 6, 2);
group.add(deflector);

// === ADDITIONAL CANOPY EDGE DETAILS ===
// Front lip overhang
const canopyLip = new THREE.Mesh(
  new THREE.BoxGeometry(24, 1.5, 1),
  steelDark
);
canopyLip.userData.textureId = "steel-panel";
canopyLip.position.set(0, 57, 9);
group.add(canopyLip);

// Back lip
const canopyLipB = new THREE.Mesh(
  new THREE.BoxGeometry(18, 1.5, 1),
  steelDark
);
canopyLipB.userData.textureId = "steel-panel";
canopyLipB.position.set(0, 57, -9);
group.add(canopyLipB);

// Side lips
const canopyLipL = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1.5, 18),
  steelDark
);
canopyLipL.userData.textureId = "steel-panel";
canopyLipL.position.set(-11, 57, 0);
group.add(canopyLipL);

const canopyLipR = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1.5, 18),
  steelDark
);
canopyLipR.userData.textureId = "steel-panel";
canopyLipR.position.set(11, 57, 0);
group.add(canopyLipR);

// === HORIZONTAL BANDING ON MAIN WINGS ===
for (let side = -1; side <= 1; side += 2) {
  for (let j = 0; j < 5; j++) {
    const band = new THREE.Mesh(
      new THREE.BoxGeometry(8.1, 0.3, 14.1),
      steelDark
    );
    band.position.set(side * 7, 8 + j * 5, 0);
    group.add(band);
  }
}

// === ADDITIONAL SCARY DETAILS ===
// Warning stripe blocks at base
const warningMat = new THREE.MeshStandardMaterial({ color: 0x332200, roughness: 0.9, side: THREE.DoubleSide });
for (let i = 0; i < 6; i++) {
  const stripe = new THREE.Mesh(
    new THREE.BoxGeometry(2, 1, 0.2),
    i % 2 === 0 ? warningMat : new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.9, side: THREE.DoubleSide })
  );
  stripe.position.set(-5 + i * 2, 5.5, 7.1);
  group.add(stripe);
}

// Small antenna/spire on top
const antenna = new THREE.Mesh(
  new THREE.CylinderGeometry(0.15, 0.15, 4, 8),
  steelMed
);
antenna.position.set(6, 61, 4);
group.add(antenna);

const antenna2 = new THREE.Mesh(
  new THREE.CylinderGeometry(0.15, 0.15, 3, 8),
  steelMed
);
antenna2.position.set(-6, 60.5, -4);
group.add(antenna2);

return group;

const group = new THREE.Group();

// Materials
const concreteMat = new THREE.MeshStandardMaterial({ color: 0xa8a8a8, roughness: 0.8, side: THREE.DoubleSide });
const concreteSmooth = new THREE.MeshStandardMaterial({ color: 0xc0c0c0, roughness: 0.6, side: THREE.DoubleSide });
const glassMat = new THREE.MeshStandardMaterial({ color: 0x8aacbc, transparent: true, opacity: 0.5, metalness: 0.5, roughness: 0.1, side: THREE.DoubleSide });
const steelMat = new THREE.MeshStandardMaterial({ color: 0x505050, roughness: 0.4, metalness: 0.7, side: THREE.DoubleSide });
const darkSteelMat = new THREE.MeshStandardMaterial({ color: 0x303030, roughness: 0.3, metalness: 0.8, side: THREE.DoubleSide });
const helipadMat = new THREE.MeshStandardMaterial({ color: 0x666666, roughness: 0.7, side: THREE.DoubleSide });
const redLightMat = new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0xff0000, emissiveIntensity: 1.2, roughness: 0.3, side: THREE.DoubleSide });
const railMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.4, metalness: 0.6, side: THREE.DoubleSide });
const whiteMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5, side: THREE.DoubleSide });
const yellowMat = new THREE.MeshStandardMaterial({ color: 0xffff00, roughness: 0.5, side: THREE.DoubleSide });
const panelMat = new THREE.MeshStandardMaterial({ color: 0x909090, roughness: 0.7, side: THREE.DoubleSide });

// Helipad platform dimensions
const platformWidth = 24;
const platformDepth = 24;
const platformHeight = 0.5;

// Main helipad platform
const platformGeo = new THREE.BoxGeometry(platformWidth, platformHeight, platformDepth);
const platform = new THREE.Mesh(platformGeo, concreteSmooth);
platform.userData.textureId = "concrete-smooth";
platform.position.set(0, 0, 0);
group.add(platform);

// Helipad surface marking - outer circle
const outerRingGeo = new THREE.RingGeometry(10, 10.3, 48);
const outerRing = new THREE.Mesh(outerRingGeo, whiteMat);
outerRing.rotation.x = -Math.PI / 2;
outerRing.position.set(0, 0.26, 0);
group.add(outerRing);

// Inner circle
const innerRingGeo = new THREE.RingGeometry(7, 7.3, 48);
const innerRing = new THREE.Mesh(innerRingGeo, whiteMat);
innerRing.rotation.x = -Math.PI / 2;
innerRing.position.set(0, 0.26, 0);
group.add(innerRing);

// H marking
const hLeftGeo = new THREE.BoxGeometry(0.8, 0.05, 4);
const hLeft = new THREE.Mesh(hLeftGeo, whiteMat);
hLeft.position.set(-2, 0.27, 0);
group.add(hLeft);

const hRightGeo = new THREE.BoxGeometry(0.8, 0.05, 4);
const hRight = new THREE.Mesh(hRightGeo, whiteMat);
hRight.position.set(2, 0.27, 0);
group.add(hRight);

const hMidGeo = new THREE.BoxGeometry(4.6, 0.05, 0.8);
const hMid = new THREE.Mesh(hMidGeo, whiteMat);
hMid.position.set(0, 0.27, 0);
group.add(hMid);

// Direction arrow
const arrowGeo = new THREE.BoxGeometry(0.5, 0.05, 3);
const arrow = new THREE.Mesh(arrowGeo, yellowMat);
arrow.position.set(0, 0.27, -6);
arrow.rotation.y = Math.PI / 4;
group.add(arrow);

const arrowHeadGeo = new THREE.ConeGeometry(0.4, 1, 4);
const arrowHead = new THREE.Mesh(arrowHeadGeo, yellowMat);
arrowHead.rotation.x = Math.PI / 2;
arrowHead.position.set(0, 0.27, -7.5);
group.add(arrowHead);

// Helipad edge marking
const edgeMarkingGeo = new THREE.TorusGeometry(11.8, 0.15, 8, 48);
const edgeMarking = new THREE.Mesh(edgeMarkingGeo, yellowMat);
edgeMarking.rotation.x = Math.PI / 2;
edgeMarking.position.set(0, 0.26, 0);
group.add(edgeMarking);

// Structural support columns
const columnPositions = [
    [-10, -10], [10, -10], [-10, 10], [10, 10],
    [-5, -10], [5, -10], [-5, 10], [5, 10],
    [-10, -5], [10, -5], [-10, 5], [10, 5]
];

columnPositions.forEach(pos => {
    const columnGeo = new THREE.CylinderGeometry(0.4, 0.4, 4, 12);
    const column = new THREE.Mesh(columnGeo, darkSteelMat);
    column.position.set(pos[0], -2, pos[1]);
    group.add(column);
});

// Support beams under platform
for (let x = -10; x <= 10; x += 5) {
    const beamGeo = new THREE.BoxGeometry(0.3, 0.3, platformDepth);
    const beam = new THREE.Mesh(beamGeo, darkSteelMat);
    beam.position.set(x, -2, 0);
    group.add(beam);
}

for (let z = -10; z <= 10; z += 5) {
    const beamGeo = new THREE.BoxGeometry(platformWidth, 0.3, 0.3);
    const beam = new THREE.Mesh(beamGeo, darkSteelMat);
    beam.position.set(0, -2, z);
    group.add(beam);
}

// Safety railing around helipad
const railRadius = 12.2;
const numRailPosts = 36;
for (let i = 0; i < numRailPosts; i++) {
    const angle = (i / numRailPosts) * Math.PI * 2;
    const rx = Math.cos(angle) * railRadius;
    const rz = Math.sin(angle) * railRadius;

    // Vertical post
