mainShaft.position.y = plinthHeight + 4 + mainShaftHeight / 2;
group.add(mainShaft);

// Gothic vertical ribs on all four sides of the shaft
const ribWidth = 1.2;
const ribDepth = 1.5;
const ribHeight = mainShaftHeight;

for (let side = 0; side < 4; side++) {
    for (let r = -1; r <= 1; r += 2) {
        const ribGeo = new THREE.BoxGeometry(ribWidth, ribHeight, ribDepth);
        const rib = new THREE.Mesh(ribGeo, darkStoneMat);
        const offset = r * (towerWidth / 2 - 3);
