        } else if (side === 1) {
            rib.position.set(offset, plinthHeight + 4 + ribHeight / 2, -towerDepth / 2 - 0.5);
        } else if (side === 2) {
            rib.position.set(towerWidth / 2 + 0.5, plinthHeight + 4 + ribHeight / 2, offset);
            rib.rotation.y = Math.PI / 2;
        } else {
            rib.position.set(-towerWidth / 2 - 0.5, plinthHeight + 4 + ribHeight / 2, offset);
            rib.rotation.y = Math.PI / 2;
        }
        group.add(rib);
    }
}

// Horizontal stone bands on the shaft
for (let b = 0; b < 5; b++) {
    const bandY = plinthHeight + 4 + (b + 1) * (mainShaftHeight / 6);
    const bandGeo = new THREE.BoxGeometry(towerWidth + 2, 1.5, towerDepth + 2);
