const clockSectionWidth = towerWidth + 4;
const clockSectionDepth = towerDepth + 4;

// Decorative ledge below clock section
const ledgeGeo = new THREE.BoxGeometry(clockSectionWidth + 4, 3, clockSectionDepth + 4);
const ledge = new THREE.Mesh(ledgeGeo, darkStoneMat);
ledge.position.y = clockSectionY + 1.5;
group.add(ledge);

const clockBoxGeo = new THREE.BoxGeometry(clockSectionWidth, clockSectionHeight, clockSectionDepth);
const clockBox = new THREE.Mesh(clockBoxGeo, stoneMat);
clockBox.position.y = clockSectionY + 3 + clockSectionHeight / 2;
group.add(clockBox);

// Clock faces on all four sides
const clockRadius = 8;
for (let side = 0; side < 4; side++) {
    const clockGeo = new THREE.CircleGeometry(clockRadius, 32);
    const clockFace = new THREE.Mesh(clockGeo, clockFaceMat);
    const cy = clockSectionY + 3 + clockSectionHeight / 2;

    if (side === 0) {
        clockFace.position.set(0, cy, clockSectionDepth / 2 + 0.3);
    } else if (side === 1) {
        clockFace.position.set(0, cy, -clockSectionDepth / 2 - 0.3);
        clockFace.rotation.y = Math.PI;
    } else if (side === 2) {
        clockFace.position.set(clockSectionWidth / 2 + 0.3, cy, 0);
        clockFace.rotation.y = Math.PI / 2;
    } else {
        clockFace.position.set(-clockSectionWidth / 2 - 0.3, cy, 0);
        clockFace.rotation.y = -Math.PI / 2;
    }
    group.add(clockFace);

    // Clock border ring
    const ringGeo = new THREE.TorusGeometry(clockRadius, 0.6, 8, 32);
    const ring = new THREE.Mesh(ringGeo, goldMat);
    ring.position.copy(clockFace.position);
    ring.rotation.copy(clockFace.rotation);
    group.add(ring);

    // Clock hands (hour and minute)
    const hourHandGeo = new THREE.BoxGeometry(0.6, clockRadius * 0.5, 0.3);
    const hourHand = new THREE.Mesh(hourHandGeo, goldMat);
    hourHand.position.copy(clockFace.position);
    hourHand.position.y += clockRadius * 0.25;
    // slight offset forward
    if (side === 0) hourHand.position.z += 0.5;
    else if (side === 1) hourHand.position.z -= 0.5;
    else if (side === 2) hourHand.position.x += 0.5;
    else hourHand.position.x -= 0.5;
    hourHand.rotation.copy(clockFace.rotation);
    group.add(hourHand);

    const minuteHandGeo = new THREE.BoxGeometry(0.4, clockRadius * 0.7, 0.3);
    const minuteHand = new THREE.Mesh(minuteHandGeo, goldMat);
    minuteHand.position.copy(clockFace.position);
    if (side === 0) { minuteHand.position.z += 0.6; minuteHand.rotation.z = Math.PI / 6; }
    else if (side === 1) { minuteHand.position.z -= 0.6; minuteHand.rotation.z = Math.PI / 4; }
    else if (side === 2) { minuteHand.position.x += 0.6; minuteHand.rotation.z = -Math.PI / 5; }
    else { minuteHand.position.x -= 0.6; minuteHand.rotation.z = Math.PI / 3; }
    minuteHand.position.y += clockRadius * 0.2;
    group.add(minuteHand);

    // Roman numeral markers (12 small boxes around the clock face)
    for (let n = 0; n < 12; n++) {
        const angle = (n / 12) * Math.PI * 2 - Math.PI / 2;
        const markerGeo = new THREE.BoxGeometry(0.4, 1.2, 0.3);
        const marker = new THREE.Mesh(markerGeo, goldMat);
        const mx = Math.cos(angle) * (clockRadius * 0.82);
        const my = Math.sin(angle) * (clockRadius * 0.82);

        marker.position.copy(clockFace.position);
        marker.rotation.copy(clockFace.rotation);

        if (side === 0) {
            marker.position.x += mx;
            marker.position.y += my;
            marker.position.z += 0.4;
        } else if (side === 1) {
            marker.position.x -= mx;
            marker.position.y += my;
            marker.position.z -= 0.4;
        } else if (side === 2) {
            marker.position.z += mx;
            marker.position.y += my;
            marker.position.x += 0.4;
        } else {
            marker.position.z -= mx;
            marker.position.y += my;
            marker.position.x -= 0.4;
        }
        // Rotate marker to point radially
        const markerRotZ = angle;
        if (side === 0 || side === 1) marker.rotation.z = markerRotZ;
        else marker.rotation.z = markerRotZ;
        group.add(marker);
    }
}

