// Create the main building footprint shape with curved front
const shape = new THREE.Shape();
const curveDepth = 1.5; // how much the front bows out

// Start at back-left
shape.moveTo(-buildingWidth / 2, -buildingDepth / 2);
// Back edge (straight)
shape.lineTo(buildingWidth / 2, -buildingDepth / 2);
// Right edge (straight)
shape.lineTo(buildingWidth / 2, buildingDepth / 2 - 1);
// Right front corner (small curve)
shape.quadraticCurveTo(buildingWidth / 2, buildingDepth / 2 + curveDepth * 0.3, buildingWidth / 2 - 2, buildingDepth / 2 + curveDepth * 0.6);
// Front edge (curved outward)
shape.quadraticCurveTo(0, buildingDepth / 2 + curveDepth, -buildingWidth / 2 + 2, buildingDepth / 2 + curveDepth * 0.6);
// Left front corner
shape.quadraticCurveTo(-buildingWidth / 2, buildingDepth / 2 + curveDepth * 0.3, -buildingWidth / 2, buildingDepth / 2 - 1);
// Left edge (straight)
shape.lineTo(-buildingWidth / 2, -buildingDepth / 2);

// --- Floor slabs and glass per floor ---
for (let floor = 0; floor < numFloors; floor++) {
