    const slabGeo = new THREE.ExtrudeGeometry(shape, slabExtrudeSettings);
    const slab = new THREE.Mesh(slabGeo, concreteMat);
    slab.userData.textureId = "concrete-precast";
    slab.rotation.x = -Math.PI / 2;
    slab.position.y = y;
