    // Glass curtain wall for each floor - using box approximations for each face
    const glassHeight = floorHeight - 0.5;

    // Front glass (slightly curved - approximate with multiple segments)
    const numSegments = 8;
    const segWidth = (buildingWidth - 4) / numSegments;
    for (let s = 0; s < numSegments; s++) {
        const t = (s + 0.5) / numSegments; // 0 to 1
        const x = -buildingWidth / 2 + 2 + s * segWidth + segWidth / 2;
        const zOffset = curveDepth * Math.sin(t * Math.PI) * 0.6;
        const angle = Math.atan2(curveDepth * Math.PI * Math.cos(t * Math.PI), buildingWidth - 4);

        const frontGlassGeo = new THREE.BoxGeometry(segWidth + 0.05, glassHeight, 0.15);
        const frontGlass = new THREE.Mesh(frontGlassGeo, glassMat);
        frontGlass.userData.textureId = "glass-curtainwall";
        frontGlass.position.set(x, y + 0.3 + glassHeight / 2, buildingDepth / 2 + zOffset + 0.6);
        frontGlass.rotation.y = angle * 0.3;
        group.add(frontGlass);
    }

    // Back glass
    const backGlassGeo = new THREE.BoxGeometry(buildingWidth - 4, glassHeight, 0.15);
    const backGlass = new THREE.Mesh(backGlassGeo, glassMat);
    backGlass.userData.textureId = "glass-curtainwall";
