const group = new THREE.Group();

// Materials
const concreteMat = new THREE.MeshStandardMaterial({ color: 0xcccccc, roughness: 0.7 });
const darkConcreteMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.8 });
const glassMat = new THREE.MeshStandardMaterial({ color: 0xaaddee, transparent: true, opacity: 0.35, metalness: 0.6, roughness: 0.1 });
const darkFrameMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.5, metalness: 0.7 });
const woodMat = new THREE.MeshStandardMaterial({ color: 0x8B6914, roughness: 0.7 });
const louverMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.6, metalness: 0.5 });
const roofMat = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.6 });

// Building dimensions based on elevations
// ~30m tall (ground + 6 floors + roof), footprint ~18x14m
const buildingWidth = 18; // X
const buildingDepth = 14; // Z
const floorHeight = 3.8;
const groundFloorHeight = 4.5;
const numUpperFloors = 6;
const totalHeight = groundFloorHeight + numUpperFloors * floorHeight; // ~27.3m
const roofHeight = 2.5;

// ========== GROUND FLOOR ==========
// Ground floor main volume - slightly recessed with darker framing
const groundGeo = new THREE.BoxGeometry(buildingWidth, groundFloorHeight, buildingDepth);
const groundMesh = new THREE.Mesh(groundGeo, concreteMat);
groundMesh.userData.textureId = "concrete-smooth";
groundMesh.position.set(0, groundFloorHeight / 2, 0);
group.add(groundMesh);

// Ground floor glass - front facade
const gfGlassGeo = new THREE.BoxGeometry(buildingWidth - 2, groundFloorHeight - 1.2, 0.15);
const gfGlass = new THREE.Mesh(gfGlassGeo, glassMat);
gfGlass.userData.textureId = "glass-curtainwall";
gfGlass.position.set(0, groundFloorHeight / 2, buildingDepth / 2 + 0.08);
group.add(gfGlass);

// Ground floor entrance canopy
const canopyGeo = new THREE.BoxGeometry(6, 0.3, 2.5);
const canopy = new THREE.Mesh(canopyGeo, darkFrameMat);
canopy.userData.textureId = "metal-zinc";
canopy.position.set(0, groundFloorHeight * 0.75, buildingDepth / 2 + 1.25);
group.add(canopy);

// Canopy supports (2 thin columns)
for (let side = -1; side <= 1; side += 2) {
  const supportGeo = new THREE.BoxGeometry(0.15, groundFloorHeight * 0.75, 0.15);
  const support = new THREE.Mesh(supportGeo, darkFrameMat);
  support.position.set(side * 2.5, groundFloorHeight * 0.75 / 2, buildingDepth / 2 + 2.3);
  group.add(support);
}

// Wood cladding panels on ground floor left side (front view)
const woodPanelGeo = new THREE.BoxGeometry(4, groundFloorHeight - 0.5, 0.2);
const woodPanel = new THREE.Mesh(woodPanelGeo, woodMat);
woodPanel.userData.textureId = "wood-siding";
woodPanel.position.set(-buildingWidth / 2 + 2, groundFloorHeight / 2, buildingDepth / 2 + 0.15);
group.add(woodPanel);

// Wood panels on sides too
for (let side = -1; side <= 1; side += 2) {
  const sideWoodGeo = new THREE.BoxGeometry(0.2, groundFloorHeight - 0.5, 3);
  const sideWood = new THREE.Mesh(sideWoodGeo, woodMat);
  sideWood.userData.textureId = "wood-siding";
  sideWood.position.set(side * (buildingWidth / 2 + 0.1), groundFloorHeight / 2, -buildingDepth / 2 + 2);
  group.add(sideWood);
}

// ========== UPPER FLOORS (1st to 6th) ==========
// The building has an asymmetric design with:
// - Left portion: vertical louver/fin system (dark)
// - Right portion: glass curtain wall
// - Central vertical glass stairwell element visible from sides

for (let floor = 0; floor < numUpperFloors; floor++) {
  const floorY = groundFloorHeight + floor * floorHeight;

  // Floor slab (visible as horizontal bands)
  const slabGeo = new THREE.BoxGeometry(buildingWidth + 0.3, 0.35, buildingDepth + 0.3);
  const slab = new THREE.Mesh(slabGeo, concreteMat);
  slab.userData.textureId = "concrete-precast";
  slab.position.set(0, floorY + 0.175, 0);
  group.add(slab);

  // Main floor volume
  const floorGeo = new THREE.BoxGeometry(buildingWidth, floorHeight - 0.35, buildingDepth);
  const floorMesh = new THREE.Mesh(floorGeo, concreteMat);
  floorMesh.userData.textureId = "concrete-smooth";
  floorMesh.position.set(0, floorY + 0.35 + (floorHeight - 0.35) / 2, 0);
  group.add(floorMesh);

  // Front facade glass - right portion (wider glass area)
  const frontGlassWidth = buildingWidth * 0.55;
  const fGlassGeo = new THREE.BoxGeometry(frontGlassWidth, floorHeight - 0.7, 0.12);
  const fGlass = new THREE.Mesh(fGlassGeo, glassMat);
  fGlass.userData.textureId = "glass-curtainwall";
  fGlass.position.set(buildingWidth / 2 - frontGlassWidth / 2 - 0.5, floorY + floorHeight / 2, buildingDepth / 2 + 0.08);
  group.add(fGlass);

  // Front facade - left portion with vertical louvers
  const louverSectionWidth = buildingWidth - frontGlassWidth - 1;
  const louverX = -buildingWidth / 2 + louverSectionWidth / 2 + 0.3;

  // Background glass behind louvers
  const bgGlassGeo = new THREE.BoxGeometry(louverSectionWidth, floorHeight - 0.7, 0.1);
  const bgGlass = new THREE.Mesh(bgGlassGeo, glassMat);
  bgGlass.userData.textureId = "glass-curtainwall";
  bgGlass.position.set(louverX, floorY + floorHeight / 2, buildingDepth / 2 + 0.05);
  group.add(bgGlass);

  // Vertical louver fins
  const numLouvers = 10;
  const louverSpacing = louverSectionWidth / numLouvers;
  for (let l = 0; l < numLouvers; l++) {
    const finGeo = new THREE.BoxGeometry(0.08, floorHeight - 0.5, 0.6);
    const fin = new THREE.Mesh(finGeo, louverMat);
    fin.userData.textureId = "metal-zinc";
    fin.position.set(
      louverX - louverSectionWidth / 2 + l * louverSpacing + louverSpacing / 2,
      floorY + floorHeight / 2,
      buildingDepth / 2 + 0.35
    );
    group.add(fin);
  }

  // Side facades - glass curtain walls
  for (let side = -1; side <= 1; side += 2) {
    const sideGlassGeo = new THREE.BoxGeometry(0.12, floorHeight - 0.7, buildingDepth - 1);
    const sideGlass = new THREE.Mesh(sideGlassGeo, glassMat);
    sideGlass.userData.textureId = "glass-curtainwall";
    sideGlass.position.set(side * (buildingWidth / 2 + 0.08), floorY + floorHeight / 2, 0);
    group.add(sideGlass);
  }

  // Rear facade - more solid with punched windows
  const rearWallGeo = new THREE.BoxGeometry(buildingWidth, floorHeight - 0.35, 0.3);
  const rearWall = new THREE.Mesh(rearWallGeo, darkConcreteMat);
  rearWall.userData.textureId = "concrete-precast";
  rearWall.position.set(0, floorY + 0.35 + (floorHeight - 0.35) / 2, -buildingDepth / 2 - 0.15);
  group.add(rearWall);

  // Rear punched windows (grid of smaller windows)
  const windowCols = 5;
  const windowWidth = 2.2;
  const windowHeight = 2.0;
  const windowSpacingX = buildingWidth / (windowCols + 1);

  for (let col = 0; col < windowCols; col++) {
    const winGeo = new THREE.BoxGeometry(windowWidth, windowHeight, 0.12);
    const win = new THREE.Mesh(winGeo, glassMat);
    win.userData.textureId = "glass-frosted";
    win.position.set(
      -buildingWidth / 2 + windowSpacingX * (col + 1),
      floorY + floorHeight / 2 + 0.2,
      -buildingDepth / 2 - 0.32
    );
    group.add(win);
