// The Gherkin (30 St Mary Axe) - London's iconic bullet-shaped tower
// Height: ~180m, distinctive curved glass form with diamond-pattern diagrid
// Roughly circular footprint ~57m diameter at widest, tapering at top and bottom

// Glass material for the main tower facades
const glassMat = new THREE.MeshStandardMaterial({
  color: 0x88bbdd,
  transparent: true,
  opacity: 0.5,
  metalness: 0.6,
  roughness: 0.1,
});

// Darker glass for alternating panels
const glassMat2 = new THREE.MeshStandardMaterial({
  color: 0x4488aa,
  transparent: true,
  opacity: 0.55,
  metalness: 0.65,
  roughness: 0.08,
});

// Steel diagrid frame material
const steelMat = new THREE.MeshStandardMaterial({
  color: 0x556677,
  metalness: 0.8,
  roughness: 0.25,
});

// Concrete for base/plaza
const concreteMat = new THREE.MeshStandardMaterial({
  color: 0xcccccc,
  roughness: 0.7,
  metalness: 0.1,
});

// Dome cap material
const domeMat = new THREE.MeshStandardMaterial({
  color: 0xaaccdd,
  transparent: true,
  opacity: 0.65,
  metalness: 0.7,
  roughness: 0.05,
});

// ============ GHERKIN PROFILE ============
// The Gherkin has a characteristic bulging profile:
// narrow at base, widest around 1/3 height, tapering to a rounded dome top
// We build it using stacked cylindrical sections (lathe-like)

const totalHeight = 180;
const numSlices = 40;
const sliceHeight = totalHeight / numSlices;
const radialSegments = 24;

// Profile function: radius at normalized height t (0=bottom, 1=top)
function gherkinRadius(t) {
  // Narrow at bottom (~10m radius), bulges to max (~14m) around t=0.35,
  // then tapers smoothly to a small dome top (~3m)
  if (t < 0.05) {
    // Ground floor taper inward slightly
    return 10 + t / 0.05 * 3.5;
  } else if (t < 0.35) {
    // Expanding belly
    const s = (t - 0.05) / 0.30;
    return 13.5 + Math.sin(s * Math.PI * 0.5) * 2.5;
  } else if (t < 0.85) {
    // Gradual taper
    const s = (t - 0.35) / 0.50;
    return 16 - s * s * 10;
  } else {
    // Dome taper to top
    const s = (t - 0.85) / 0.15;
    return Math.max(1.5, 6 * (1 - s * s));
  }
}

// ============ BASE PLAZA / PODIUM ============
const plazaGeo = new THREE.CylinderGeometry(20, 22, 2, 32);
const plaza = new THREE.Mesh(plazaGeo, concreteMat);
plaza.position.set(0, 1, 0);
plaza.userData.textureId = "concrete-smooth";
group.add(plaza);

// Slightly raised ring around base
const baseRingGeo = new THREE.TorusGeometry(13, 0.6, 8, 32);
const baseRing = new THREE.Mesh(baseRingGeo, steelMat);
baseRing.rotation.x = Math.PI / 2;
baseRing.position.set(0, 2.5, 0);
baseRing.userData.textureId = "metal-zinc";
group.add(baseRing);

// ============ MAIN TOWER BODY ============
// Build from stacked truncated cone sections
for (let i = 0; i < numSlices; i++) {
  const t1 = i / numSlices;
  const t2 = (i + 1) / numSlices;
  const r1 = gherkinRadius(t1);
  const r2 = gherkinRadius(t2);
  const y = 2 + i * sliceHeight;

  const sliceGeo = new THREE.CylinderGeometry(r2, r1, sliceHeight, radialSegments, 1, true);
  const mat = (i % 2 === 0) ? glassMat : glassMat2;
  const slice = new THREE.Mesh(sliceGeo, mat);
  slice.position.set(0, y + sliceHeight / 2, 0);
  slice.userData.textureId = "glass-curtainwall";
  group.add(slice);
}

// ============ DOME CAP ============
const domeRadius = gherkinRadius(1.0) + 0.5;
const domeGeo = new THREE.SphereGeometry(3.5, radialSegments, 12, 0, Math.PI * 2, 0, Math.PI / 2);
const dome = new THREE.Mesh(domeGeo, domeMat);
dome.position.set(0, 2 + totalHeight, 0);
dome.userData.textureId = "glass-curtainwall";
group.add(dome);

// Small antenna/pinnacle on top
const antennaGeo = new THREE.CylinderGeometry(0.15, 0.3, 6, 8);
const antenna = new THREE.Mesh(antennaGeo, steelMat);
antenna.position.set(0, 2 + totalHeight + 3 + 3, 0);
antenna.userData.textureId = "metal-zinc";
group.add(antenna);

// ============ DIAGRID STRUCTURE ============
// The Gherkin's most distinctive feature: diamond-shaped diagonal steel grid
// Spiraling helical steel members

const diagridSlices = 30;
const diagridStrands = 18; // number of helical strands going each direction

function createDiagridHelix(startAngle, direction, color) {
  // direction: 1 = CW going up, -1 = CCW going up
  const points = [];
  const segCount = diagridSlices * 2;
  for (let j = 0; j <= segCount; j++) {
    const t = j / segCount;
    const y = 2 + t * totalHeight;
    const r = gherkinRadius(t) + 0.15;
    const angle = startAngle + direction * t * Math.PI * 6; // 3 full rotations
    const x = Math.cos(angle) * r;
    const z = Math.sin(angle) * r;
    points.push(new THREE.Vector3(x, y, z));
  }

  // Build tube along these points
  const curve = new THREE.CatmullRomCurve3(points);
  const tubeGeo = new THREE.TubeGeometry(curve, segCount * 2, 0.12, 4, false);
  const mesh = new THREE.Mesh(tubeGeo, steelMat);
  mesh.userData.textureId = "metal-zinc";
  return mesh;
}

// Create helical diagrid strands in both directions
for (let s = 0; s < diagridStrands; s++) {
  const angle = (s / diagridStrands) * Math.PI * 2;
  const helixCW = createDiagridHelix(angle, 1);
  group.add(helixCW);
  const helixCCW = createDiagridHelix(angle, -1);
  group.add(helixCCW);
}

// ============ HORIZONTAL FLOOR RINGS ============
// Floor plates visible as subtle horizontal bands

for (let i = 0; i < numSlices; i += 2) {
  const t = (i + 0.5) / numSlices;
  const r = gherkinRadius(t) + 0.2;
  const y = 2 + (i + 0.5) * sliceHeight;

  if (r < 2) continue;

  const ringGeo = new THREE.TorusGeometry(r, 0.08, 4, radialSegments);
  const ring = new THREE.Mesh(ringGeo, steelMat);
  ring.rotation.x = Math.PI / 2;
  ring.position.set(0, y, 0);
  ring.userData.textureId = "metal-zinc";
  group.add(ring);
}

// ============ GROUND LEVEL ENTRANCE ============
// The Gherkin has a ground floor set back with visible columns

const numColumns = 12;
for (let c = 0; c < numColumns; c++) {
  const angle = (c / numColumns) * Math.PI * 2;
  const r = 10.5;
  const colGeo = new THREE.CylinderGeometry(0.35, 0.35, 8, 8);
  const col = new THREE.Mesh(colGeo, steelMat);
  col.position.set(Math.cos(angle) * r, 6, Math.sin(angle) * r);
  col.userData.textureId = "metal-zinc";
  group.add(col);
}

// Glass ground floor curtain wall (set back from main body)
const groundGlassGeo = new THREE.CylinderGeometry(10, 10, 8, radialSegments, 1, true);
const groundGlass = new THREE.Mesh(groundGlassGeo, new THREE.MeshStandardMaterial({
