group.add(canopy);

// Canopy supports
for (let i = -1; i <= 1; i += 2) {
  const supportGeo = new THREE.CylinderGeometry(0.1, 0.1, 4, 8);
  const support = new THREE.Mesh(supportGeo, steelMat);
