// ============ TOP RESTAURANT LEVEL / LENS CAP ============
// The top floors have a distinctive lens-shaped enclosure
const lensGeo = new THREE.SphereGeometry(5, radialSegments, 8, 0, Math.PI * 2, 0.3, 0.7);
const lensMat = new THREE.MeshStandardMaterial({
  color: 0xbbddee,
  transparent: true,
