});
const lens = new THREE.Mesh(lensGeo, lensMat);
lens.position.set(0, totalHeight - 5, 0);
lens.userData.textureId = "glass-curtainwall";
group.add(lens);

// ============ VENTILATION SPIRALS (dark bands) ============
// The Gherkin has characteristic dark spiral openings for natural ventilation
// These are visible as darker triangular patches spiraling up the facade

for (let s = 0; s < 6; s++) {
  const startAngle = (s / 6) * Math.PI * 2;
  const ventPoints = [];
  const ventSegs = 40;
  for (let j = 0; j <= ventSegs; j++) {
    const t = 0.08 + (j / ventSegs) * 0.72;
    const y = 2 + t * totalHeight;
    const r = gherkinRadius(t) + 0.3;
    const angle = startAngle + t * Math.PI * 6;
    ventPoints.push(new THREE.Vector3(Math.cos(angle) * r, y, Math.sin(angle) * r));
  }
  const ventCurve = new THREE.CatmullRomCurve3(ventPoints);
  const ventGeo = new THREE.TubeGeometry(ventCurve, ventSegs * 2, 0.35, 3, false);
  const ventMat = new THREE.MeshStandardMaterial({
    color: 0x223344,
    metalness: 0.3,
    roughness: 0.6,
    transparent: true,
    opacity: 0.7,
  });
  const ventMesh = new THREE.Mesh(ventGeo, ventMat);
  ventMesh.userData.textureId = "glass-curtainwall";
  group.add(ventMesh);
}

return group;

