// Clock hands (simple)
function addClockHands(cx, cy, cz, rotAxis) {
    const handMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a });
    // Hour hand
    const hourGeo = new THREE.BoxGeometry(0.1, 1.0, 0.1);
    const hour = new THREE.Mesh(hourGeo, handMat);
    hour.position.set(cx, cy + 0.3, cz);
    if (rotAxis === 'x') { hour.position.z = cz; hour.position.set(cx, cy + 0.3, cz > 0 ? cz + 0.2 : cz - 0.2); }
    if (rotAxis === 'z') { hour.position.set(cx > 0 ? cx + 0.2 : cx - 0.2, cy + 0.3, cz); }
    group.add(hour);
    // Minute hand
    const minGeo = new THREE.BoxGeometry(0.08, 1.5, 0.08);
    const min = new THREE.Mesh(minGeo, handMat);
    min.rotation.z = Math.PI / 6;
    min.position.set(cx, cy, cz > 0 ? cz + 0.2 : rotAxis === 'z' ? cz : cz - 0.2);
    if (rotAxis === 'z') min.position.set(cx > 0 ? cx + 0.2 : cx - 0.2, cy, cz);
    group.add(min);
}

