// Function to create one tower
function createTower(centerX, centerZ, height, hasAntenna) {
  const towerGroup = new THREE.Group();

  // The WTC towers had distinctive vertical ribbing and horizontal band divisions
  // Each tower was divided into 3 vertical sections by the mechanical floors
  // Mechanical floor bands at roughly 1/3 and 2/3 height, plus near top

  const sectionHeights = [
    { start: 0, end: height * 0.28 },    // Lower section
    { start: height * 0.28, end: height * 0.31 }, // Mechanical band 1
    { start: height * 0.31, end: height * 0.60 }, // Middle section
    { start: height * 0.60, end: height * 0.63 }, // Mechanical band 2
    { start: height * 0.63, end: height * 0.92 }, // Upper section
    { start: height * 0.92, end: height * 0.95 }, // Mechanical band 3 (top)
    { start: height * 0.95, end: height }          // Top cap
  ];

  // Main tower sections with vertical ribbing texture
  for (let i = 0; i < sectionHeights.length; i++) {
    const section = sectionHeights[i];
    const sectionH = section.end - section.start;
    const isMechanical = (i === 1 || i === 3 || i === 5);

    const geo = new THREE.BoxGeometry(towerWidth, sectionH, towerDepth);
    const mat = isMechanical ? windowBandMat : facadeMat;
    const mesh = new THREE.Mesh(geo, mat);

    if (isMechanical) {
      mesh.userData.textureId = "concrete-precast";
    } else {
      mesh.userData.textureId = "glass-curtainwall";
    }

    mesh.position.set(centerX, section.start + sectionH / 2, centerZ);
    towerGroup.add(mesh);
  }

  // Create vertical column strips on each face to simulate the iconic ribbed facade
  const numColumns = 8; // simplified representation of the many columns
  const columnWidth = 0.3;
  const columnDepth = 0.4;

  for (let face = 0; face < 4; face++) {
    for (let c = 0; c < numColumns; c++) {
      const t = (c + 0.5) / numColumns;
      const pos = -towerWidth / 2 + t * towerWidth;

      const colGeo = new THREE.BoxGeometry(
        face < 2 ? columnWidth : columnDepth,
        height,
        face < 2 ? columnDepth : columnWidth
      );
      const colMesh = new THREE.Mesh(colGeo, facadeDarkMat);

      let cx = centerX, cz = centerZ;
      if (face === 0) { // front
        cx = centerX + pos - towerWidth / 2 + towerWidth * t;
        cx = centerX - towerWidth / 2 + t * towerWidth;
        cz = centerZ + towerDepth / 2;
      } else if (face === 1) { // back
        cx = centerX - towerWidth / 2 + t * towerWidth;
        cz = centerZ - towerDepth / 2;
      } else if (face === 2) { // right
        cx = centerX + towerWidth / 2;
        cz = centerZ - towerDepth / 2 + t * towerDepth;
      } else { // left
        cx = centerX - towerWidth / 2;
        cz = centerZ - towerDepth / 2 + t * towerDepth;
      }

      colMesh.position.set(cx, height / 2, cz);
      colMesh.userData.textureId = "steel-panel";
      towerGroup.add(colMesh);
    }
  }

  // Rooftop - flat roof with mechanical equipment
  const roofGeo = new THREE.BoxGeometry(towerWidth, 1, towerDepth);
  const roofMesh = new THREE.Mesh(roofGeo, concreteMat);
  roofMesh.userData.textureId = "concrete-smooth";
  roofMesh.position.set(centerX, height + 0.5, centerZ);
  towerGroup.add(roofMesh);

  // Rooftop mechanical box
  const mechBoxGeo = new THREE.BoxGeometry(towerWidth * 0.6, 5, towerDepth * 0.6);
  const mechBox = new THREE.Mesh(mechBoxGeo, concreteMat);
  mechBox.userData.textureId = "concrete-smooth";
  mechBox.position.set(centerX, height + 3.5, centerZ);
  towerGroup.add(mechBox);

  // Antenna (North Tower - WTC 1)
  if (hasAntenna) {
    // Main antenna mast
    const antennaGeo = new THREE.CylinderGeometry(0.4, 0.8, antennaHeight * 0.7, 8);
    const antennaMesh = new THREE.Mesh(antennaGeo, antennaMat);
    antennaMesh.userData.textureId = "steel-panel";
    antennaMesh.position.set(centerX, height + 6 + antennaHeight * 0.35, centerZ);
    towerGroup.add(antennaMesh);

    // Antenna tip (thinner)
    const antennaTipGeo = new THREE.CylinderGeometry(0.15, 0.4, antennaHeight * 0.3, 8);
    const antennaTip = new THREE.Mesh(antennaTipGeo, antennaMat);
    antennaTip.userData.textureId = "steel-panel";
    antennaTip.position.set(centerX, height + 6 + antennaHeight * 0.7 + antennaHeight * 0.15, centerZ);
    towerGroup.add(antennaTip);

    // Antenna base platform
    const antBasGeo = new THREE.CylinderGeometry(2, 2.5, 4, 8);
    const antBas = new THREE.Mesh(antBasGeo, antennaMat);
    antBas.userData.textureId = "steel-panel";
    antBas.position.set(centerX, height + 4, centerZ);
    towerGroup.add(antBas);

    // Cross braces on antenna
    for (let b = 0; b < 3; b++) {
      const braceY = height + 6 + antennaHeight * 0.2 * (b + 1);
      const braceGeo = new THREE.BoxGeometry(3, 0.3, 0.3);
      const brace1 = new THREE.Mesh(braceGeo, antennaMat);
      brace1.position.set(centerX, braceY, centerZ);
      towerGroup.add(brace1);

      const brace2 = new THREE.Mesh(braceGeo, antennaMat);
      brace2.position.set(centerX, braceY, centerZ);
      brace2.rotation.y = Math.PI / 2;
      towerGroup.add(brace2);
    }
  }

  return towerGroup;
}

