// The Shard's form consists of multiple overlapping glass planes
// that taper to a point but don't all meet at the same apex,
// creating the distinctive "shard of glass" open-top spire

// Main tower body - we'll build it from multiple tapered shapes
// representing the different glass facets

// Helper function to create a tapered panel (facet of the tower)
function createFacet(baseWidth, baseDepth, topWidth, topDepth, height, offsetX, offsetZ, topOffsetX, topOffsetZ, material) {
  const shape = new THREE.Shape();
  // Base rectangle
  const hw = baseWidth / 2;
  const hd = baseDepth / 2;
  shape.moveTo(-hw, -hd);
  shape.lineTo(hw, -hd);
  shape.lineTo(hw, hd);
  shape.lineTo(-hw, hd);
  shape.closePath();

  // Use BufferGeometry approach - build custom geometry
  const geo = new THREE.BufferGeometry();
  const thw = topWidth / 2;
  const thd = topDepth / 2;

  // 8 vertices: 4 bottom, 4 top
  const bx = offsetX;
  const bz = offsetZ;
  const tx = topOffsetX;
  const tz = topOffsetZ;

  const vertices = new Float32Array([
    // Bottom face
    bx - hw, 0, bz - hd,      // 0
    bx + hw, 0, bz - hd,      // 1
    bx + hw, 0, bz + hd,      // 2
    bx - hw, 0, bz + hd,      // 3
    // Top face
    tx - thw, height, tz - thd, // 4
    tx + thw, height, tz - thd, // 5
    tx + thw, height, tz + thd, // 6
    tx - thw, height, tz + thd, // 7
  ]);

  // Build faces as triangles
  const positions = [];
  const normals = [];

  function addQuad(a, b, c, d) {
    // Two triangles: a-b-c and a-c-d
    const va = [vertices[a*3], vertices[a*3+1], vertices[a*3+2]];
    const vb = [vertices[b*3], vertices[b*3+1], vertices[b*3+2]];
    const vc = [vertices[c*3], vertices[c*3+1], vertices[c*3+2]];
    const vd = [vertices[d*3], vertices[d*3+1], vertices[d*3+2]];

    // Calculate normal
    const e1 = [vb[0]-va[0], vb[1]-va[1], vb[2]-va[2]];
    const e2 = [vc[0]-va[0], vc[1]-va[1], vc[2]-va[2]];
    const nx = e1[1]*e2[2] - e1[2]*e2[1];
    const ny = e1[2]*e2[0] - e1[0]*e2[2];
    const nz = e1[0]*e2[1] - e1[1]*e2[0];
    const len = Math.sqrt(nx*nx + ny*ny + nz*nz) || 1;

    positions.push(...va, ...vb, ...vc);
    positions.push(...va, ...vc, ...vd);
    for (let i = 0; i < 6; i++) {
      normals.push(nx/len, ny/len, nz/len);
    }
  }

  // Front face (z-)
  addQuad(0, 1, 5, 4);
  // Right face (x+)
  addQuad(1, 2, 6, 5);
  // Back face (z+)
  addQuad(2, 3, 7, 6);
  // Left face (x-)
  addQuad(3, 0, 4, 7);
  // Top face
  addQuad(4, 5, 6, 7);
  // Bottom face
  addQuad(3, 2, 1, 0);

  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));

  const mesh = new THREE.Mesh(geo, material);
  return mesh;
}

