// Section heights and dimensions for the main pyramidal form
const sections = [
  // [baseY, height, baseW, baseD, topW, topD, bOffX, bOffZ, tOffX, tOffZ]
  [15, 50, 26, 24, 22, 20, 0, 0, 0, 0],      // 15-65m
