// Thin tapered blade
function createSpireBlade(width, depth, height, baseY, offsetX, offsetZ, rotY) {
  const geo = new THREE.BoxGeometry(width, height, depth);
  const mat = new THREE.MeshStandardMaterial({
    color: 0xd0dde8,
    transparent: true,
    opacity: 0.6,
    metalness: 0.7,
    roughness: 0.05,
  });
  const mesh = new THREE.Mesh(geo, mat);

  // Taper using vertices
  const posAttr = geo.attributes.position;
  for (let i = 0; i < posAttr.count; i++) {
    const y = posAttr.getY(i);
    if (y > 0) {
      // Top vertices - scale down
      const scale = 0.05;
      posAttr.setX(i, posAttr.getX(i) * scale);
      posAttr.setZ(i, posAttr.getZ(i) * scale);
    }
  }
  posAttr.needsUpdate = true;
  geo.computeVertexNormals();

  mesh.position.set(offsetX, baseY + height / 2, offsetZ);
  mesh.rotation.y = rotY;
  mesh.userData.textureId = "glass-curtainwall";
  return mesh;
}

