// ============ VERTICAL EDGE LINES / MULLIONS ============
// The Shard has prominent vertical lines running up its edges

function createEdgeLine(x1, z1, x2, z2, y1, y2) {
  const height = y2 - y1;
  const dx = x2 - x1;
  const dz = z2 - z1;
  const length = Math.sqrt(dx * dx + dz * dz);

  // Thin box as edge line
  const geo = new THREE.BoxGeometry(0.15, height, 0.15);
  const mesh = new THREE.Mesh(geo, steelMat);
  mesh.userData.textureId = "metal-zinc";

  // Interpolate position
  mesh.position.set(
    (x1 + x2) / 2,
    (y1 + y2) / 2,
    (z1 + z2) / 2
  );

  return mesh;
}

// Main corner edges of the pyramidal form
// These run from base to near the top, tapering inward
const edgeSegments = 20;
for (let i = 0; i < edgeSegments; i++) {
  const t1 = i / edgeSegments;
  const t2 = (i + 1) / edgeSegments;
  const y1 = 15 + t1 * 265;
  const y2 = 15 + t2 * 265;

  // Four main corners tapering to center
  const corners = [
    [13, 12],   // front-right
    [-13, 12],  // front-left
    [13, -12],  // back-right
    [-13, -12], // back-left
  ];

  corners.forEach(([cx, cz]) => {
    const x1 = cx * (1 - t1 * 0.96);
    const z1 = cz * (1 - t1 * 0.96);
    const x2 = cx * (1 - t2 * 0.96);
    const z2 = cz * (1 - t2 * 0.96);

    const edge = createEdgeLine(x1, z1, x2, z2, y1, y2);
    group.add(edge);
  });
}

