// ============ DIAGONAL FACET LINES ============
// The Shard's facade has subtle diagonal seams where glass planes meet
// These create the distinctive "shard" appearance

function createDiagonalSeam(x1, y1, z1, x2, y2, z2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const dz = z2 - z1;
  const length = Math.sqrt(dx*dx + dy*dy + dz*dz);

  const geo = new THREE.CylinderGeometry(0.08, 0.08, length, 4);
  const mesh = new THREE.Mesh(geo, steelMat);
  mesh.userData.textureId = "metal-zinc";

  mesh.position.set((x1+x2)/2, (y1+y2)/2, (z1+z2)/2);

  // Orient along the direction
  const dir = new THREE.Vector3(dx, dy, dz).normalize();
  const up = new THREE.Vector3(0, 1, 0);
  const quat = new THREE.Quaternion().setFromUnitVectors(up, dir);
  mesh.quaternion.copy(quat);

  return mesh;
}

