const steelMat = new THREE.MeshStandardMaterial({ color: 0xc0c8d0, roughness: 0.3, metalness: 0.8 });
const glassMat = new THREE.MeshStandardMaterial({ color: 0x4a6a7a, transparent: true, opacity: 0.6, metalness: 0.7, roughness: 0.1 });
const lightSteelMat = new THREE.MeshStandardMaterial({ color: 0xd8dde2, roughness: 0.4, metalness: 0.7 });
