const spireMatl = new THREE.MeshStandardMaterial({ color: 0xe8e8f0, roughness: 0.2, metalness: 0.9 });

// Helper: create a tapered cylindrical tower section (Petronas towers have a stepped/tapered profile)
function createTowerBody(xOffset, zOffset) {
    const towerGroup = new THREE.Group();

    // Petronas towers have an 8-pointed star cross-section approximated here
    // Main tower body - use CylinderGeometry with 8 sides for the Islamic geometric motif
    const numSegments = 8;

    // Lower section (wider)
    const lowerGeo = new THREE.CylinderGeometry(7, 7.5, 70, numSegments);
    const lower = new THREE.Mesh(lowerGeo, glassMat);
    lower.userData.textureId = "glass-curtainwall";
    lower.position.set(0, 35, 0);
    towerGroup.add(lower);

    // Middle section (slight taper)
    const midGeo = new THREE.CylinderGeometry(6.2, 7, 40, numSegments);
    const mid = new THREE.Mesh(midGeo, glassMat);
    mid.userData.textureId = "glass-curtainwall";
    mid.position.set(0, 90, 0);
    towerGroup.add(mid);

    // Upper section (more taper)
    const upperGeo = new THREE.CylinderGeometry(5, 6.2, 30, numSegments);
    const upper = new THREE.Mesh(upperGeo, glassMat);
    upper.userData.textureId = "glass-curtainwall";
    upper.position.set(0, 125, 0);
    towerGroup.add(upper);

    // Top crown section
    const crownGeo = new THREE.CylinderGeometry(3.5, 5, 15, numSegments);
    const crown = new THREE.Mesh(crownGeo, glassMat);
    crown.userData.textureId = "glass-curtainwall";
    crown.position.set(0, 147.5, 0);
    towerGroup.add(crown);

    // Ring-like crown cap
    const capGeo = new THREE.CylinderGeometry(4.2, 3.5, 3, numSegments);
    const cap = new THREE.Mesh(capGeo, steelMat);
    cap.userData.textureId = "metal-brushed";
    cap.position.set(0, 156.5, 0);
    towerGroup.add(cap);

    // Spire (pinnacle) - tall thin spire on top
    const spireGeo = new THREE.CylinderGeometry(0.2, 0.8, 30, 8);
    const spire = new THREE.Mesh(spireGeo, spireMatl);
    spire.userData.textureId = "metal-brushed";
    spire.position.set(0, 173, 0);
    towerGroup.add(spire);

    // Spire tip
    const spireTipGeo = new THREE.ConeGeometry(0.2, 5, 8);
    const spireTip = new THREE.Mesh(spireTipGeo, spireMatl);
    spireTip.userData.textureId = "metal-brushed";
    spireTip.position.set(0, 190.5, 0);
    towerGroup.add(spireTip);

    // Vertical steel fins on each face (the prominent vertical ribs)
    for (let i = 0; i < numSegments; i++) {
        const angle = (i / numSegments) * Math.PI * 2;
        const finRadius = 7.7;

        // Lower fins
        const finGeo = new THREE.BoxGeometry(0.6, 145, 0.6);
        const fin = new THREE.Mesh(finGeo, lightSteelMat);
        fin.userData.textureId = "metal-brushed";
        fin.position.set(
            Math.cos(angle) * finRadius,
            72.5,
            Math.sin(angle) * finRadius
        );
        fin.rotation.y = -angle;
        towerGroup.add(fin);
    }

    // Semi-circular bumps between the 8 points (creating the star shape effect)
    for (let i = 0; i < numSegments; i++) {
        const angle = ((i + 0.5) / numSegments) * Math.PI * 2;
        const bumpRadius = 8.5;

        const bumpGeo = new THREE.CylinderGeometry(1.8, 2, 70, 6);
        const bump = new THREE.Mesh(bumpGeo, glassMat);
        bump.userData.textureId = "glass-curtainwall";
        bump.position.set(
            Math.cos(angle) * bumpRadius,
            35,
            Math.sin(angle) * bumpRadius
        );
        towerGroup.add(bump);

        // Upper bumps (smaller)
        const bumpGeo2 = new THREE.CylinderGeometry(1.3, 1.8, 40, 6);
        const bump2 = new THREE.Mesh(bumpGeo2, glassMat);
        bump2.userData.textureId = "glass-curtainwall";
        bump2.position.set(
            Math.cos(angle) * (bumpRadius - 0.8),
            90,
            Math.sin(angle) * (bumpRadius - 0.8)
        );
        towerGroup.add(bump2);
    }

    // Horizontal floor bands (every ~4 units)
    for (let y = 2; y < 155; y += 4) {
        let radius;
        if (y < 70) radius = 7.6;
        else if (y < 110) radius = 6.7 + (70 - Math.min(y, 110)) * 0.01;
        else if (y < 140) radius = 5.7;
        else radius = 4.0;

        const bandGeo = new THREE.TorusGeometry(radius, 0.15, 4, numSegments);
        const band = new THREE.Mesh(bandGeo, lightSteelMat);
        band.userData.textureId = "metal-brushed";
        band.position.set(0, y, 0);
        band.rotation.x = Math.PI / 2;
        towerGroup.add(band);
    }

    towerGroup.position.set(xOffset, 0, zOffset);
    return towerGroup;
}

