roofShape.lineTo(roofW2, -roofD2);
roofShape.lineTo(roofW2, roofD2);
roofShape.lineTo(-roofW2, roofD2);
roofShape.closePath();

// Build a custom hip roof geometry
const roofHeight = 4.5;
const roofGeo = new THREE.BufferGeometry();
const ridgeInset = 8;
const roofVerts = [
  // Base corners (bottom of roof)
  -roofW2, 0, -roofD2,   // 0
  roofW2, 0, -roofD2,    // 1
  roofW2, 0, roofD2,     // 2
  -roofW2, 0, roofD2,    // 3
  // Ridge line (top)
  -roofW2 + ridgeInset, roofHeight, 0,  // 4
  roofW2 - ridgeInset, roofHeight, 0,   // 5
];

const roofPositions = [];
const roofNormals = [];

function addTriangle(v0, v1, v2, verts) {
  const a = [verts[v0*3], verts[v0*3+1], verts[v0*3+2]];
  const b = [verts[v1*3], verts[v1*3+1], verts[v1*3+2]];
  const c = [verts[v2*3], verts[v2*3+1], verts[v2*3+2]];
  const e1 = [b[0]-a[0], b[1]-a[1], b[2]-a[2]];
  const e2 = [c[0]-a[0], c[1]-a[1], c[2]-a[2]];
  const nx = e1[1]*e2[2] - e1[2]*e2[1];
  const ny = e1[2]*e2[0] - e1[0]*e2[2];
  const nz = e1[0]*e2[1] - e1[1]*e2[0];
  const len = Math.sqrt(nx*nx + ny*ny + nz*nz) || 1;
  roofPositions.push(...a, ...b, ...c);
  roofNormals.push(nx/len, ny/len, nz/len, nx/len, ny/len, nz/len, nx/len, ny/len, nz/len);
}

const rv = [
  -roofW2, 0, -roofD2,
  roofW2, 0, -roofD2,
  roofW2, 0, roofD2,
  -roofW2, 0, roofD2,
  -roofW2 + ridgeInset, roofHeight, 0,
  roofW2 - ridgeInset, roofHeight, 0,
];

// Front slope (z+)
addTriangle(3, 2, 5, rv);
addTriangle(3, 5, 4, rv);
// Back slope (z-)
addTriangle(0, 4, 5, rv);
addTriangle(0, 5, 1, rv);
// Left hip
addTriangle(3, 4, 0, rv);
// Right hip
addTriangle(2, 1, 5, rv);

