// Windows on the main building - 3 floors of windows
function createWindow(x, y, z, rotY) {
  const winGroup = new THREE.Group();

  // Window pane
  const paneGeo = new THREE.BoxGeometry(1.6, 2.8, 0.15);
  const pane = new THREE.Mesh(paneGeo, windowMat);
  pane.userData.textureId = "glass-curtainwall";
  winGroup.add(pane);

  // Window frame
  const frameGeo = new THREE.BoxGeometry(1.9, 3.1, 0.08);
  const frame = new THREE.Mesh(frameGeo, trimMat);
  frame.position.z = -0.05;
  frame.userData.textureId = "stone-limestone";
  winGroup.add(frame);

  // Window sill
  const sillGeo = new THREE.BoxGeometry(2.1, 0.2, 0.5);
  const sill = new THREE.Mesh(sillGeo, trimMat);
  sill.position.set(0, -1.6, 0.1);
  sill.userData.textureId = "stone-limestone";
  winGroup.add(sill);

  // Window lintel/pediment
  const lintelGeo = new THREE.BoxGeometry(2.2, 0.35, 0.4);
  const lintel = new THREE.Mesh(lintelGeo, trimMat);
  lintel.position.set(0, 1.7, 0.1);
  lintel.userData.textureId = "stone-limestone";
  winGroup.add(lintel);

  // Mullion (vertical divider)
  const mullionGeo = new THREE.BoxGeometry(0.08, 2.8, 0.18);
  const mullion = new THREE.Mesh(mullionGeo, trimMat);
  mullion.userData.textureId = "stone-limestone";
  winGroup.add(mullion);

  // Horizontal muntin
  const muntinGeo = new THREE.BoxGeometry(1.6, 0.06, 0.18);
  const muntin = new THREE.Mesh(muntinGeo, trimMat);
  muntin.position.y = 0.3;
  muntin.userData.textureId = "stone-limestone";
  winGroup.add(muntin);

  winGroup.position.set(x, y, z);
  winGroup.rotation.y = rotY || 0;
  return winGroup;
}

