for (let floor = 0; floor < 2; floor++) {
  const y = 5.5 + floor * 5.5;
  for (let i = 0; i < frontWindowCount; i++) {
    const x = -((frontWindowCount - 1) / 2) * frontWindowSpacing + i * frontWindowSpacing;
    // Skip windows where the door is (center 2)
    if (floor === 0 && Math.abs(x) < 2) continue;
    // Skip windows behind the north portico columns area on ground floor
    if (floor === 0 && Math.abs(x) < 7) continue;
    const win = createWindow(x, y, -(mainD / 2 + 0.1), 0);
    group.add(win);
  }
}

// Back (south) facade windows
for (let floor = 0; floor < 2; floor++) {
  const y = 5.5 + floor * 5.5;
  for (let i = 0; i < frontWindowCount; i++) {
    const x = -((frontWindowCount - 1) / 2) * frontWindowSpacing + i * frontWindowSpacing;
    if (Math.abs(x) < bowRadius + 1) continue;
    const win = createWindow(x, y, mainD / 2 + 0.1, Math.PI);
    group.add(win);
  }
}

