  // Wing hip roof
  const wRoofH = 3;
  const wRoofGeo = new THREE.BufferGeometry();
  const wRW = (wingW + 1.5) / 2;
  const wRD = (wingD + 1.5) / 2;
  const wri = 4;
  const wrv = [
    -wRW, 0, -wRD,
    wRW, 0, -wRD,
    wRW, 0, wRD,
    -wRW, 0, wRD,
    -wRW + wri, wRoofH, 0,
    wRW - wri, wRoofH, 0,
  ];
  const wrPositions = [];
  const wrNorms = [];

  function addTriWR(v0, v1, v2) {
    const a = [wrv[v0*3], wrv[v0*3+1], wrv[v0*3+2]];
    const b = [wrv[v1*3], wrv[v1*3+1], wrv[v1*3+2]];
    const c = [wrv[v2*3], wrv[v2*3+1], wrv[v2*3+2]];
    const e1 = [b[0]-a[0], b[1]-a[1], b[2]-a[2]];
    const e2 = [c[0]-a[0], c[1]-a[1], c[2]-a[2]];
    const nx = e1[1]*e2[2] - e1[2]*e2[1];
    const ny = e1[2]*e2[0] - e1[0]*e2[2];
    const nz = e1[0]*e2[1] - e1[1]*e2[0];
    const len = Math.sqrt(nx*nx + ny*ny + nz*nz) || 1;
    wrPositions.push(...a, ...b, ...c);
    wrNorms.push(nx/len,ny/len,nz/len, nx/len,ny/len,nz/len, nx/len,ny/len,nz/len);
  }

  addTriWR(3, 2, 5);
  addTriWR(3, 5, 4);
  addTriWR(0, 4, 5);
  addTriWR(0, 5, 1);
  addTriWR(3, 4, 0);
  addTriWR(2, 1, 5);

  wRoofGeo.setAttribute('position', new THREE.Float32BufferAttribute(wrPositions, 3));
  wRoofGeo.setAttribute('normal', new THREE.Float32BufferAttribute(wrNorms, 3));

  const wRoofMesh = new THREE.Mesh(wRoofGeo, roofMat);
  wRoofMesh.position.set(wingX, wingH + 0.8, 0);
  wRoofMesh.userData.textureId = "roof-slate";
  group.add(wRoofMesh);

  // Wing windows
  for (let floor = 0; floor < 1; floor++) {
    const wy = 4.5 + floor * 4;
