      const wx = wingX - 7.5 + j * 5;
      const winN = createWindow(wx, wy, -(wingD / 2 + 0.1), 0);
      group.add(winN);
      const winS = createWindow(wx, wy, wingD / 2 + 0.1, Math.PI);
      group.add(winS);
    }
  }

  // Colonnade connecting wing to main building
  const colonnadeLen = 6;
  const colonnadeH = 6;
  for (let ci = 0; ci < 3; ci++) {
    const connX = side > 0
      ? mainW / 2 + 1.5 + ci * 2.5
      : -(mainW / 2 + 1.5 + ci * 2.5);
    const connColGeo = new THREE.CylinderGeometry(0.35, 0.4, colonnadeH, 8);
    const connCol = new THREE.Mesh(connColGeo, columnMat);
    connCol.position.set(connX, colonnadeH / 2, -(wingD / 2 + 0.5));
    connCol.userData.textureId = "stone-limestone";
    group.add(connCol);

    const connCol2 = connCol.clone();
    connCol2.position.z = wingD / 2 + 0.5;
    group.add(connCol2);
  }

  // Colonnade roof beam
  const connBeamGeo = new THREE.BoxGeometry(colonnadeLen + 2, 0.6, wingD + 2);
  const connBeam = new THREE.Mesh(connBeamGeo, whiteStoneMat);
  connBeam.position.set(
    side > 0 ? mainW / 2 + colonnadeLen / 2 + 0.5 : -(mainW / 2 + colonnadeLen / 2 + 0.5),
    colonnadeH + 0.3,
    0
  );
  connBeam.userData.textureId = "stone-limestone";
  group.add(connBeam);
}

