function createWindow(x, y, z, w, h, rotY) {
  const wGroup = new THREE.Group();

  // Frame
  const wfGeo = new THREE.BoxGeometry(w + 0.2, h + 0.2, 0.15);
  const wfMesh = new THREE.Mesh(wfGeo, frameMat);
  wfMesh.userData.textureId = "steel-panel";
  wGroup.add(wfMesh);

  // Glass
  const wgGeo = new THREE.BoxGeometry(w, h, 0.05);
  const wgMesh = new THREE.Mesh(wgGeo, glassMat);
  wgMesh.position.z = -0.03;
  wgMesh.userData.textureId = "glass-curtainwall";
  wGroup.add(wgMesh);

  // Horizontal mullion
  const mhGeo = new THREE.BoxGeometry(w, 0.06, 0.06);
  const mh = new THREE.Mesh(mhGeo, frameMat);
  mh.position.set(0, h * 0.3, -0.05);
  wGroup.add(mh);

  // Vertical mullion
  const mvGeo = new THREE.BoxGeometry(0.06, h, 0.06);
  const mv = new THREE.Mesh(mvGeo, frameMat);
  mv.position.set(0, 0, -0.05);
  wGroup.add(mv);

  wGroup.position.set(x, y, z);
  if (rotY) wGroup.rotation.y = rotY;
  return wGroup;
}

