function addDiagonalBrace(x1, y1, z, x2, y2, thickness) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const length = Math.sqrt(dx * dx + dy * dy);
  const angle = Math.atan2(dy, dx);
  const brace = new THREE.Mesh(
    new THREE.BoxGeometry(length, thickness, thickness),
    timberMat
  );
  brace.position.set((x1 + x2) / 2, (y1 + y2) / 2, z);
  brace.rotation.z = angle;
  brace.userData.textureId = "wood-siding";
  group.add(brace);
}

