  ft.position.set(x, y + h / 2, z);
  ft.rotation.y = rotY || 0;
  ft.userData.textureId = "wood-siding";
  group.add(ft);
  // Bottom
  const fb = new THREE.Mesh(new THREE.BoxGeometry(w + 0.1, frameThick, 0.12), timberMat);
  fb.position.set(x, y - h / 2, z);
  fb.rotation.y = rotY || 0;
