  group.add(fb);
  // Left
  const fl = new THREE.Mesh(new THREE.BoxGeometry(frameThick, h + 0.1, 0.12), timberMat);
  fl.position.set(x - w / 2, y, z);
  fl.rotation.y = rotY || 0;
  fl.userData.textureId = "wood-siding";
  group.add(fl);
  // Right
  const fr = new THREE.Mesh(new THREE.BoxGeometry(frameThick, h + 0.1, 0.12), timberMat);
  fr.position.set(x + w / 2, y, z);
  fr.rotation.y = rotY || 0;
  fr.userData.textureId = "wood-siding";
  group.add(fr);

  // Lead lines (diamond pattern) - vertical and horizontal dividers
  const divV = new THREE.Mesh(new THREE.BoxGeometry(0.03, h, 0.09), new THREE.MeshStandardMaterial({ color: 0x444444, side: THREE.DoubleSide }));
  divV.position.set(x, y, z);
  divV.rotation.y = rotY || 0;
  group.add(divV);
  const divH = new THREE.Mesh(new THREE.BoxGeometry(w, 0.03, 0.09), new THREE.MeshStandardMaterial({ color: 0x444444, side: THREE.DoubleSide }));
  divH.position.set(x, y, z);
  divH.rotation.y = rotY || 0;
  group.add(divH);
}

