// ========== ROOF ==========
// Main gable roof running left-right (ridge along X axis... actually looking at elevations, ridge runs along Z)
// From the front elevation: the roof slopes left and right with a dormer window
// From the side elevation: we see the gable end
// So the ridge runs front-to-back (along Z axis)

const roofGroup = new THREE.Group();
roofGroup.position.set(0, upperTopY, 0);

// Roof using custom geometry - two sloped planes
const roofOverhangX = 1.0;
const roofOverhangZ = 1.5;
const halfW = upperFloorWidth / 2 + roofOverhangX;
const halfD = upperFloorDepth / 2 + roofOverhangZ;

// Left slope
const leftRoofShape = new THREE.BufferGeometry();
const leftVerts = new Float32Array([
  -halfW, 0, halfD,
  0, roofHeight, halfD,
  0, roofHeight, -halfD,
  -halfW, 0, -halfD
]);
const leftIndices = [0, 1, 2, 0, 2, 3];
leftRoofShape.setAttribute('position', new THREE.BufferAttribute(leftVerts, 3));
leftRoofShape.setIndex(leftIndices);
leftRoofShape.computeVertexNormals();
const leftRoof = new THREE.Mesh(leftRoofShape, roofMat);
leftRoof.userData.textureId = "roof-tiles";
roofGroup.add(leftRoof);

// Right slope
const rightRoofShape = new THREE.BufferGeometry();
const rightVerts = new Float32Array([
  halfW, 0, halfD,
  0, roofHeight, halfD,
  0, roofHeight, -halfD,
  halfW, 0, -halfD
]);
const rightIndices = [0, 2, 1, 0, 3, 2];
rightRoofShape.setAttribute('position', new THREE.BufferAttribute(rightVerts, 3));
rightRoofShape.setIndex(rightIndices);
rightRoofShape.computeVertexNormals();
const rightRoof = new THREE.Mesh(rightRoofShape, roofMat);
rightRoof.userData.textureId = "roof-tiles";
roofGroup.add(rightRoof);

// Roof thickness - add a thin box under each slope for thickness
const roofThickness = 0.2;
const slopeLen = Math.sqrt((halfW) * (halfW) + roofHeight * roofHeight);
const slopeAngle = Math.atan2(roofHeight, halfW);

const leftThickGeo = new THREE.BoxGeometry(slopeLen, roofThickness, upperFloorDepth + roofOverhangZ * 2);
const leftThick = new THREE.Mesh(leftThickGeo, roofMat);
leftThick.position.set(-halfW / 2, roofHeight / 2, 0);
leftThick.rotation.z = slopeAngle;
leftThick.userData.textureId = "roof-tiles";
roofGroup.add(leftThick);

const rightThickGeo = new THREE.BoxGeometry(slopeLen, roofThickness, upperFloorDepth + roofOverhangZ * 2);
const rightThick = new THREE.Mesh(rightThickGeo, roofMat);
rightThick.position.set(halfW / 2, roofHeight / 2, 0);
rightThick.rotation.z = -slopeAngle;
rightThick.userData.textureId = "roof-tiles";
roofGroup.add(rightThick);

// Gable end walls (triangles on front and back)
function makeGable(zPos, mat, texId) {
  const gableGeo = new THREE.BufferGeometry();
  const gW = upperFloorWidth / 2;
  const verts = new Float32Array([
    -gW, 0, zPos,
    gW, 0, zPos,
    0, roofHeight, zPos
  ]);
  gableGeo.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  gableGeo.setIndex([0, 1, 2]);
  gableGeo.computeVertexNormals();
  const gable = new THREE.Mesh(gableGeo, mat);
  gable.userData.textureId = texId;
  return gable;
}

// Side gable ends (brick)
