roofGroup.add(frontGable);
const backGable = makeGable(-upperFloorDepth / 2, brickMat, "brick-red");
roofGroup.add(backGable);

// Back side of gable triangles
const frontGableBack = makeGable(upperFloorDepth / 2 - 0.01, brickMat, "brick-red");
frontGableBack.scale.z = -1;
roofGroup.add(frontGableBack);
const backGableBack = makeGable(-upperFloorDepth / 2 + 0.01, brickMat, "brick-red");
backGableBack.scale.z = -1;
