function addWindow(x, y, z, w, h, rotY) {
  const winGroup = new THREE.Group();

  // Window pane
  const paneGeo = new THREE.BoxGeometry(w, h, 0.08);
  const pane = new THREE.Mesh(paneGeo, windowMat);
  pane.userData.textureId = "glass-curtainwall";
  winGroup.add(pane);

  // Window frame
  const frameThick = 0.06;
  // Top
  const topFrame = new THREE.Mesh(new THREE.BoxGeometry(w + 0.1, frameThick, 0.12), timberMat);
  topFrame.position.y = h / 2;
  topFrame.userData.textureId = "wood-siding";
  winGroup.add(topFrame);
  // Bottom
  const botFrame = new THREE.Mesh(new THREE.BoxGeometry(w + 0.1, frameThick, 0.12), timberMat);
  botFrame.position.y = -h / 2;
  botFrame.userData.textureId = "wood-siding";
  winGroup.add(botFrame);
  // Left
  const lFrame = new THREE.Mesh(new THREE.BoxGeometry(frameThick, h, 0.12), timberMat);
  lFrame.position.x = -w / 2;
  lFrame.userData.textureId = "wood-siding";
  winGroup.add(lFrame);
  // Right
  const rFrame = new THREE.Mesh(new THREE.BoxGeometry(frameThick, h, 0.12), timberMat);
  rFrame.position.x = w / 2;
  rFrame.userData.textureId = "wood-siding";
  winGroup.add(rFrame);
  // Center mullion vertical
  const mullionV = new THREE.Mesh(new THREE.BoxGeometry(0.04, h, 0.1), timberMat);
  mullionV.userData.textureId = "wood-siding";
  winGroup.add(mullionV);
  // Center mullion horizontal
  const mullionH = new THREE.Mesh(new THREE.BoxGeometry(w, 0.04, 0.1), timberMat);
  mullionH.userData.textureId = "wood-siding";
  winGroup.add(mullionH);

  winGroup.position.set(x, y, z);
  winGroup.rotation.y = rotY || 0;
  group.add(winGroup);
}

