// Actually let's build the roof with custom geometry
function buildRoofSlope(x1, y1, z1, x2, y2, z2, x3, y3, z3, x4, y4, z4, mat) {
  const geo = new THREE.BufferGeometry();
  const vertices = new Float32Array([
    x1, y1, z1, x2, y2, z2, x3, y3, z3,
    x1, y1, z1, x3, y3, z3, x4, y4, z4
  ]);
  geo.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
  geo.computeVertexNormals();
  const mesh = new THREE.Mesh(geo, mat);
  mesh.userData.textureId = "roof-tiles";
  group.add(mesh);
  return mesh;
}

// Left slope (negative X side)
buildRoofSlope(
  -rw, roofY, rd,
  0, roofY + rh, rd,
  0, roofY + rh, -rd,
  -rw, roofY, -rd,
  roofMat
);

// Right slope (positive X side)
buildRoofSlope(
  rw, roofY, rd,
  rw, roofY, -rd,
  0, roofY + rh, -rd,
  0, roofY + rh, rd,
  roofMat
);

// Front gable triangle
function buildTriangle(x1, y1, z1, x2, y2, z2, x3, y3, z3, mat, texId) {
  const geo = new THREE.BufferGeometry();
  const vertices = new Float32Array([x1, y1, z1, x2, y2, z2, x3, y3, z3]);
  geo.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
  geo.computeVertexNormals();
  const mesh = new THREE.Mesh(geo, mat);
  mesh.userData.textureId = texId;
  group.add(mesh);
  return mesh;
}

