function addWindow(x, y, z, w, h, rotY, withShutters) {
  // Window frame
  const frame = new THREE.Mesh(
    new THREE.BoxGeometry(w + 0.15, h + 0.15, 0.15),
    timberMat
  );
  frame.position.set(x, y, z);
  frame.rotation.y = rotY || 0;
  frame.userData.textureId = "wood-siding";
  group.add(frame);

  // Glass pane
  const glass = new THREE.Mesh(
    new THREE.BoxGeometry(w, h, 0.05),
    glassMat
  );
  glass.position.set(x, y, z);
  glass.rotation.y = rotY || 0;
  glass.userData.textureId = "glass-curtainwall";
  group.add(glass);

  // Diamond lattice lines (cross bars)
  const bar1 = new THREE.Mesh(
    new THREE.BoxGeometry(w, 0.04, 0.06),
    timberMat
  );
  bar1.position.set(x, y, z);
  bar1.rotation.y = rotY || 0;
  bar1.userData.textureId = "wood-siding";
  group.add(bar1);

  const bar2 = new THREE.Mesh(
    new THREE.BoxGeometry(0.04, h, 0.06),
    timberMat
  );
  bar2.position.set(x, y, z);
  bar2.rotation.y = rotY || 0;
  bar2.userData.textureId = "wood-siding";
  group.add(bar2);

  if (withShutters) {
    // Left shutter
    const lShutter = new THREE.Mesh(
      new THREE.BoxGeometry(w / 2 + 0.05, h + 0.1, 0.1),
      shutterMat
    );
    const shutterOffset = w / 2 + w / 4 + 0.05;
    if (rotY) {
      const cos = Math.cos(rotY);
      const sin = Math.sin(rotY);
      lShutter.position.set(x - shutterOffset * cos, y, z + shutterOffset * sin);
    } else {
      lShutter.position.set(x - shutterOffset, y, z);
    }
    lShutter.rotation.y = rotY || 0;
    lShutter.userData.textureId = "wood-siding";
    group.add(lShutter);

    // Right shutter
    const rShutter = new THREE.Mesh(
      new THREE.BoxGeometry(w / 2 + 0.05, h + 0.1, 0.1),
      shutterMat
    );
    if (rotY) {
      const cos = Math.cos(rotY);
      const sin = Math.sin(rotY);
      rShutter.position.set(x + shutterOffset * cos, y, z - shutterOffset * sin);
    } else {
      rShutter.position.set(x + shutterOffset, y, z);
    }
    rShutter.rotation.y = rotY || 0;
    rShutter.userData.textureId = "wood-siding";
    group.add(rShutter);
  }
}

