// ============ DORMER WINDOWS ============
function addDormer(x, z, facing) {
  const dW = 1.5;
  const dH = 1.8;
  const dD = 1.5;
  const dY = roofY + 1.5;

  // Dormer box
  const dormerBox = new THREE.Mesh(
    new THREE.BoxGeometry(dW, dH, dD),
    plasterMat
  );
  dormerBox.position.set(x, dY + dH / 2, z);
  dormerBox.userData.textureId = "stucco-white";
  group.add(dormerBox);

  // Dormer roof (small peaked)
  const drh = 0.8;
  const drw = dW / 2 + 0.2;
  const dFrontZ = facing > 0 ? z + dD / 2 : z - dD / 2;
  const dBackZ = facing > 0 ? z - dD / 2 - 0.1 : z + dD / 2 + 0.1;

  buildRoofSlope(
    x - drw, dY + dH, dFrontZ,
    x, dY + dH + drh, dFrontZ,
    x, dY + dH + drh, dBackZ,
    x - drw, dY + dH, dBackZ,
    roofMat
  );
  buildRoofSlope(
    x + drw, dY + dH, dFrontZ,
    x + drw, dY + dH, dBackZ,
    x, dY + dH + drh, dBackZ,
    x, dY + dH + drh, dFrontZ,
    roofMat
  );

  // Dormer window
  const winZ = facing > 0 ? z + dD / 2 + 0.1 : z - dD / 2 - 0.1;
  addWindow(x, dY + dH / 2, winZ, 0.8, 1.2, 0, false);
}

