function createGable(z, facingFront) {
    const shape = new THREE.Shape();
    shape.moveTo(-mainWidth / 2, 0);
    shape.lineTo(mainWidth / 2, 0);
    shape.lineTo(0, roofPeakHeight);
    shape.closePath();

    const geo = new THREE.ShapeGeometry(shape);
    const mesh = new THREE.Mesh(geo, plasterMat);
    mesh.userData.textureId = "stucco-white";

    if (facingFront) {
        mesh.position.set(cx, totalWallHeight, z);
    } else {
        mesh.rotation.y = Math.PI;
        mesh.position.set(cx, totalWallHeight, z);
    }
    return mesh;
}

