// Roof using custom geometry
function createRoofSide(isLeft) {
    const hw = mainWidth / 2 + roofOverhang;
    const hl = mainDepth / 2 + roofOverhang;
    const peakY = totalWallHeight + roofPeakHeight;
    const baseY = totalWallHeight - 0.1;

    const vertices = new Float32Array(isLeft ? [
        // Triangle 1
        cx - hw, baseY, cz - hl,
        cx, peakY, cz - hl,
        cx - hw, baseY, cz + hl,
        // Triangle 2
        cx, peakY, cz - hl,
        cx, peakY, cz + hl,
        cx - hw, baseY, cz + hl,
    ] : [
        // Triangle 1
        cx + hw, baseY, cz - hl,
        cx + hw, baseY, cz + hl,
        cx, peakY, cz - hl,
        // Triangle 2
        cx, peakY, cz - hl,
        cx + hw, baseY, cz + hl,
        cx, peakY, cz + hl,
    ]);

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
    geo.computeVertexNormals();
    const mesh = new THREE.Mesh(geo, roofMat);
    mesh.userData.textureId = "roof-tiles";
    return mesh;
}

