        cx, peakY - roofThickness, cz - hl,
        cx, peakY - roofThickness, cz - hl,
        cx - hw, baseY - roofThickness, cz + hl,
        cx, peakY - roofThickness, cz + hl,
    ] : [
        cx + hw, baseY - roofThickness, cz - hl,
        cx, peakY - roofThickness, cz - hl,
        cx + hw, baseY - roofThickness, cz + hl,
        cx, peakY - roofThickness, cz - hl,
        cx, peakY - roofThickness, cz + hl,
        cx + hw, baseY - roofThickness, cz + hl,
    ]);

    const geo = new THREE.BufferGeometry();
