// Curved roof using bezier curves for organic hobbit look
const segments = 20;
for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const angle = Math.PI * t;
    const x = -roofHalfW + (2 * roofHalfW) * t;
    // Slightly flattened ellipse with organic bumps
    const y = Math.sin(angle) * roofH * (1.0 + 0.05 * Math.sin(angle * 3));
    if (i === 0) {
        roofProfile.lineTo(x, y);
    } else {
        roofProfile.lineTo(x, y);
    }
}
roofProfile.lineTo(roofHalfW, 0);
roofProfile.closePath();

