// === HELPER: Create a single tower ===
function createTower(xPos) {
    const towerGroup = new THREE.Group();
    towerGroup.position.x = xPos;

    // Each tower has two legs connected by cross-braces at multiple levels
    const legOffsetZ = 1.2; // half-spacing between legs

    // Tower legs - tapered slightly
    for (let side = -1; side <= 1; side += 2) {
        const legGroup = new THREE.Group();

        // Lower leg section (below deck) - wider
        const lowerLegGeo = new THREE.BoxGeometry(towerLegWidth + 0.3, deckHeight, towerLegDepth);
        const lowerLeg = new THREE.Mesh(lowerLegGeo, towerMat);
        lowerLeg.userData.textureId = "steel-panel";
        lowerLeg.position.set(0, deckHeight / 2, side * legOffsetZ);
        towerGroup.add(lowerLeg);

        // Upper leg section (above deck) - slightly narrower
        const upperHeight = towerHeight - deckHeight;
        const upperLegGeo = new THREE.BoxGeometry(towerLegWidth, upperHeight, towerLegDepth - 0.2);
        const upperLeg = new THREE.Mesh(upperLegGeo, towerMat);
        upperLeg.userData.textureId = "steel-panel";
        upperLeg.position.set(0, deckHeight + upperHeight / 2, side * legOffsetZ);
        towerGroup.add(upperLeg);

        // Art Deco stepped details on tower legs - portals/openings
        // Upper cross-braces with openings (the rectangular portals visible in images)
        const portalHeights = [deckHeight + 5, deckHeight + 14, deckHeight + 21];
        portalHeights.forEach((ph) => {
            // Small horizontal brace between legs at portal level
            const braceGeo = new THREE.BoxGeometry(towerLegWidth - 0.2, 0.3, 0.3);
            const brace = new THREE.Mesh(braceGeo, towerMat);
            brace.position.set(0, ph, side * legOffsetZ);
            towerGroup.add(brace);
        });
    }

    // Cross-braces between legs (horizontal members)
    const bracePositions = [
        2, 5, 8, 11, // below deck
        deckHeight + 3, deckHeight + 8, deckHeight + 13, deckHeight + 18, deckHeight + 22 // above deck
    ];

    bracePositions.forEach((h) => {
        const braceGeo = new THREE.BoxGeometry(towerLegWidth * 0.6, 0.4, legOffsetZ * 2);
        const brace = new THREE.Mesh(braceGeo, towerMat);
        brace.position.set(0, h, 0);
        towerGroup.add(brace);
    });

    // Tower top portals (the distinctive rectangular openings)
    // Create the portal openings effect by adding surrounding frame pieces
    const portalLevels = [
        { y: deckHeight + 5, height: 4 },
        { y: deckHeight + 13, height: 4 },
        { y: deckHeight + 20, height: 3 }
    ];

    portalLevels.forEach((portal) => {
        // Top bar of portal
        const topBar = new THREE.BoxGeometry(towerLegWidth + 0.5, 0.5, legOffsetZ * 2 + towerLegDepth);
        const topMesh = new THREE.Mesh(topBar, towerMat);
        topMesh.position.set(0, portal.y + portal.height / 2, 0);
        towerGroup.add(topMesh);

        // Bottom bar of portal
        const botBar = new THREE.BoxGeometry(towerLegWidth + 0.5, 0.5, legOffsetZ * 2 + towerLegDepth);
        const botMesh = new THREE.Mesh(botBar, towerMat);
        botMesh.position.set(0, portal.y - portal.height / 2, 0);
        towerGroup.add(botMesh);
    });

    // Tower cap / finial at top
    const capGeo = new THREE.BoxGeometry(towerLegWidth + 0.8, 1.5, towerLegDepth + legOffsetZ * 2 + 0.4);
    for (let side = -1; side <= 1; side += 2) {
        const cap = new THREE.Mesh(capGeo, towerMat);
        cap.position.set(0, towerHeight + 0.75, side * legOffsetZ);
        // Individual leg caps
        const legCapGeo = new THREE.BoxGeometry(towerLegWidth + 0.2, 1.0, towerLegDepth + 0.2);
        const legCap = new THREE.Mesh(legCapGeo, towerMat);
        legCap.position.set(0, towerHeight + 0.5, side * legOffsetZ);
        towerGroup.add(legCap);

        // Stepped top detail
        const step1 = new THREE.BoxGeometry(towerLegWidth - 0.2, 0.6, towerLegDepth - 0.2);
        const stepMesh1 = new THREE.Mesh(step1, towerMat);
        stepMesh1.position.set(0, towerHeight + 1.3, side * legOffsetZ);
        towerGroup.add(stepMesh1);

        const step2 = new THREE.BoxGeometry(towerLegWidth - 0.5, 0.5, towerLegDepth - 0.5);
        const stepMesh2 = new THREE.Mesh(step2, towerMat);
        stepMesh2.position.set(0, towerHeight + 1.8, side * legOffsetZ);
        towerGroup.add(stepMesh2);
    }

    // Base/anchorage at bottom
    const baseGeo = new THREE.BoxGeometry(towerBaseWidth + 1, 2, towerBaseDepth + legOffsetZ * 2 + 1);
    const base = new THREE.Mesh(baseGeo, baseMat);
    base.userData.textureId = "concrete-smooth";
    base.position.set(0, 1, 0);
    towerGroup.add(base);

    return towerGroup;
}

