// === MAIN CABLES ===
// The main cables form a catenary curve between tower tops, draping down to deck level at center
function createMainCable(zOffset) {
    const cablePoints = [];
    const numSegments = 80;
    const startX = -totalDeckLength / 2;
    const endX = totalDeckLength / 2;
    const tower1X = -towerSpacing / 2;
    const tower2X = towerSpacing / 2;
    const cableTopY = towerHeight - 0.5;
    const cableLowY = deckHeight + 1.5;

    for (let i = 0; i <= numSegments; i++) {
        const t = i / numSegments;
        const x = startX + t * (endX - startX);
        let y;

        if (x < tower1X) {
            // Left approach - cable goes from deck level up to tower top
            const localT = (x - startX) / (tower1X - startX);
            y = cableLowY + (cableTopY - cableLowY) * localT;
        } else if (x > tower2X) {
            // Right approach - cable goes from tower top down to deck level
            const localT = (x - tower2X) / (endX - tower2X);
            y = cableTopY - (cableTopY - cableLowY) * localT;
        } else {
            // Between towers - catenary/parabolic curve
            const mid = (tower1X + tower2X) / 2;
            const halfSpan = (tower2X - tower1X) / 2;
            const normalizedX = (x - mid) / halfSpan; // -1 to 1
            y = cableLowY + (cableTopY - cableLowY) * normalizedX * normalizedX;
        }

        cablePoints.push(new THREE.Vector3(x, y, zOffset));
    }

    // Create tube geometry for the cable
    const curve = new THREE.CatmullRomCurve3(cablePoints);
    const tubeGeo = new THREE.TubeGeometry(curve, numSegments, 0.15, 8, false);
    const cable = new THREE.Mesh(tubeGeo, cableMat);
    return cable;
}

