// === SUSPENDER CABLES (vertical cables from main cable to deck) ===
function getSuspenderCableY(x, zOffset) {
    const tower1X = -towerSpacing / 2;
    const tower2X = towerSpacing / 2;
    const cableTopY = towerHeight - 0.5;
    const cableLowY = deckHeight + 1.5;
    const startX = -totalDeckLength / 2;
    const endX = totalDeckLength / 2;

    if (x < tower1X) {
        const localT = (x - startX) / (tower1X - startX);
        return cableLowY + (cableTopY - cableLowY) * localT;
    } else if (x > tower2X) {
        const localT = (x - tower2X) / (endX - tower2X);
        return cableTopY - (cableTopY - cableLowY) * localT;
    } else {
        const mid = (tower1X + tower2X) / 2;
        const halfSpan = (tower2X - tower1X) / 2;
        const normalizedX = (x - mid) / halfSpan;
        return cableLowY + (cableTopY - cableLowY) * normalizedX * normalizedX;
    }
}

