// === VERTICAL WINDOW STRIPS ON TOWER (Art Deco style) ===
function addVerticalWindowStrip(x, z, h, w, rotY) {
  const stripGeo = new THREE.BoxGeometry(w, h, 0.2);
  const strip = new THREE.Mesh(stripGeo, windowMat);
  strip.position.set(x, totalTowerBase + h / 2, z);
  if (rotY) strip.rotation.y = rotY;
  strip.userData.textureId = "glass-curtainwall";
  group.add(strip);

  // Gold spandrel accents
  for (let j = 0; j < 9; j++) {
    const spanGeo = new THREE.BoxGeometry(w + 0.1, 0.15, 0.25);
    const span = new THREE.Mesh(spanGeo, goldMat);
    span.position.set(x, totalTowerBase + 2.5 + j * 4.8, z);
    if (rotY) span.rotation.y = rotY;
    group.add(span);
  }
}

// Front tower windows
for (let i = -1; i <= 1; i++) {
  addVerticalWindowStrip(i * 3.2, -towerD / 2 - 0.1, towerH, 2.0, 0);
}

// Back tower windows
for (let i = -1; i <= 1; i++) {
  addVerticalWindowStrip(i * 3.2, towerD / 2 + 0.1, towerH, 2.0, 0);
}

// Side tower windows
for (let i = -1; i <= 1; i++) {
  addVerticalWindowStrip(-towerW / 2 - 0.1, i * 2.8, towerH, 1.8, Math.PI / 2);
  addVerticalWindowStrip(towerW / 2 + 0.1, i * 2.8, towerH, 1.8, Math.PI / 2);
}

// === BASE LEVEL WINDOWS ===
function addRectWindow(x, y, z, w, h, rotY) {
  const winGeo = new THREE.BoxGeometry(w, h, 0.15);
  const win = new THREE.Mesh(winGeo, windowMat);
  win.position.set(x, y, z);
  if (rotY) win.rotation.y = rotY;
  win.userData.textureId = "glass-curtainwall";
  group.add(win);

  const mullVGeo = new THREE.BoxGeometry(0.06, h, 0.17);
  const mullV = new THREE.Mesh(mullVGeo, darkMat);
  mullV.position.set(x, y, z);
  if (rotY) mullV.rotation.y = rotY;
  group.add(mullV);

  const mullHGeo = new THREE.BoxGeometry(w, 0.06, 0.17);
  const mullH = new THREE.Mesh(mullHGeo, darkMat);
  mullH.position.set(x, y, z);
  if (rotY) mullH.rotation.y = rotY;
  group.add(mullH);
}

