// === BATTLEMENTS / CRENELLATIONS on walls ===
function addCrenellations(startX, startZ, length, direction, yBase) {
  // direction: 'x' for along X axis, 'z' for along Z axis
  const merlonW = 0.8;
  const merlonH = 1.2;
  const merlonD = 1.2;
  const gap = 0.7;
  const step = merlonW + gap;
  const count = Math.floor(length / step);

  for (let i = 0; i < count; i++) {
    const merlonGeo = new THREE.BoxGeometry(
      direction === 'x' ? merlonW : merlonD,
      merlonH,
      direction === 'z' ? merlonW : merlonD
    );
    const merlon = new THREE.Mesh(merlonGeo, stoneMat);
    merlon.userData.textureId = "stone-ashlar";
    if (direction === 'x') {
      merlon.position.set(startX + i * step - length / 2 + merlonW / 2, yBase + merlonH / 2, startZ);
    } else {
      merlon.position.set(startX, yBase + merlonH / 2, startZ + i * step - length / 2 + merlonW / 2);
    }
    group.add(merlon);
  }
}

