function createCornerTower(x, z) {
  const towerGroup = new THREE.Group();

  // Tower body - cylindrical
  const towerGeo = new THREE.CylinderGeometry(2.2, 2.4, 12, 16);
  const tower = new THREE.Mesh(towerGeo, stoneMat);
  tower.userData.textureId = "stone-ashlar";
  tower.position.y = 6.8;
  towerGroup.add(tower);

  // Tower base - slightly wider
  const baseGeo = new THREE.CylinderGeometry(2.4, 2.8, 2, 16);
  const base = new THREE.Mesh(baseGeo, stoneBaseMat);
  base.userData.textureId = "stone-granite";
  base.position.y = 1;
  towerGroup.add(base);

  // Conical roof
  const roofGeo = new THREE.ConeGeometry(2.8, 3.5, 16);
  const roof = new THREE.Mesh(roofGeo, roofMat);
  roof.userData.textureId = "roof-tiles";
  roof.position.y = 14.55;
  towerGroup.add(roof);

  // Roof spire
  const spireGeo = new THREE.CylinderGeometry(0.05, 0.15, 1.5, 8);
  const spire = new THREE.Mesh(spireGeo, darkStoneMat);
  spire.position.y = 17.05;
  towerGroup.add(spire);

  // Tower crenellations (circular)
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const mGeo = new THREE.BoxGeometry(0.8, 1, 0.6);
    const m = new THREE.Mesh(mGeo, stoneMat);
    m.userData.textureId = "stone-ashlar";
    m.position.set(Math.cos(angle) * 2.2, 13.3, Math.sin(angle) * 2.2);
    m.lookAt(new THREE.Vector3(0, 13.3, 0).add(towerGroup.position));
    m.rotation.y = angle;
    towerGroup.add(m);
  }

  // Windows (arrow slits)
  for (let j = 0; j < 3; j++) {
    const slitGeo = new THREE.BoxGeometry(0.25, 1.2, 0.3);
    const slit = new THREE.Mesh(slitGeo, windowMat);
    const angle = (x > 0 ? -1 : 1) * Math.PI / 4;
    slit.position.set(
      Math.cos(angle + j * 0.8) * 2.25,
      4 + j * 3,
      Math.sin(angle + j * 0.8) * 2.25
    );
    slit.rotation.y = angle + j * 0.8;
    towerGroup.add(slit);
  }

  towerGroup.position.set(x, 0, z);
  return towerGroup;
}

