const buildingDepth = 22;   // Z
const baseHeight = 7;       // Ground floor brick section
const secondHeight = 6;     // Second floor
const totalWallHeight = baseHeight + secondHeight; // 13
const roofPeakExtra = 4;    // Saw-tooth roof peaks above wall top

// ========== MAIN BUILDING BODY ==========

// Ground floor - brick base (full footprint)
const baseGeo = new THREE.BoxGeometry(buildingWidth, baseHeight, buildingDepth);
const baseMesh = new THREE.Mesh(baseGeo, brickMat);
baseMesh.position.set(0, baseHeight / 2, 0);
baseMesh.userData.textureId = "brick-red";
