// ========== SAW-TOOTH ROOF ==========
// Create 4 saw-tooth sections across the width
const numTeeth = 4;
const toothWidth = buildingWidth / numTeeth;
const toothDepth = buildingDepth;
const toothHeight = roofPeakExtra;

for (let i = 0; i < numTeeth; i++) {
    const xOffset = -buildingWidth / 2 + toothWidth / 2 + i * toothWidth;

    // Each tooth: a right-triangle prism shape
    // Sloped side faces front (negative Z), vertical side faces back
    const shape = new THREE.Shape();
    shape.moveTo(0, 0);
    shape.lineTo(toothWidth, 0);
    shape.lineTo(toothWidth, toothHeight);
    shape.lineTo(0, 0);

    const extrudeSettings = { depth: toothDepth, bevelEnabled: false };
    const toothGeo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
    const toothMesh = new THREE.Mesh(toothGeo, roofMat);
    toothMesh.userData.textureId = "steel-panel";

    // Position: rotate so extrusion goes along Z
    toothMesh.rotation.y = Math.PI / 2;
    toothMesh.position.set(xOffset + toothWidth / 2, totalWallHeight, -toothDepth / 2);
    group.add(toothMesh);

    // Vertical glass face on each tooth (clerestory window facing back/north)
    const glassGeo = new THREE.PlaneGeometry(toothDepth, toothHeight);
    const glassMesh = new THREE.Mesh(glassGeo, glassMat);
    glassMesh.userData.textureId = "glass-curtainwall";
    glassMesh.rotation.y = Math.PI / 2;
    glassMesh.position.set(xOffset + toothWidth / 2, totalWallHeight + toothHeight / 2, 0);
    group.add(glassMesh);

    // Small roof cap on top of each tooth
    const capGeo = new THREE.BoxGeometry(0.3, toothHeight, toothDepth);
    const capMesh = new THREE.Mesh(capGeo, darkMat);
    capMesh.position.set(xOffset + toothWidth / 2, totalWallHeight + toothHeight / 2, 0);
    capMesh.userData.textureId = "steel-panel";
    group.add(capMesh);
}

