// Helper functions
function makeBox(w, h, d, mat, x, y, z, textureId) {
  const geo = new THREE.BoxGeometry(w, h, d);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y, z);
  if (textureId) mesh.userData.textureId = textureId;
  return mesh;
}

function makeCylinder(rTop, rBot, h, segs, mat, x, y, z, textureId) {
  const geo = new THREE.CylinderGeometry(rTop, rBot, h, segs);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y, z);
  if (textureId) mesh.userData.textureId = textureId;
  return mesh;
}

