function createTower(tx, tz) {
  const towerGroup = new THREE.Group();

  // Tower base extension above mansard
  const towerBaseY = ridgeY;
  const towerW = 3.5;
  const towerSectionH = 4;

  // Tower drum (square base)
  towerGroup.add(makeBox(towerW, towerSectionH, towerW, stoneMat, tx, towerBaseY + towerSectionH / 2, tz, "stone-ashlar"));

  // Tower windows (4 sides)
  const towerWinOffsets = [
    { dx: 0, dz: towerW / 2 + 0.05, rw: 1.0, rh: 2.0, rd: 0.1 },
    { dx: 0, dz: -(towerW / 2 + 0.05), rw: 1.0, rh: 2.0, rd: 0.1 },
    { dx: towerW / 2 + 0.05, dz: 0, rw: 0.1, rh: 2.0, rd: 1.0 },
    { dx: -(towerW / 2 + 0.05), dz: 0, rw: 0.1, rh: 2.0, rd: 1.0 }
  ];
  towerWinOffsets.forEach(tw => {
    towerGroup.add(makeBox(tw.rw, tw.rh, tw.rd, glassMat, tx + tw.dx, towerBaseY + towerSectionH / 2 + 0.3, tz + tw.dz, "glass-curtainwall"));
  });

  // Tower cornice
  const towerCorniceY = towerBaseY + towerSectionH;
  towerGroup.add(makeBox(towerW + 0.4, 0.3, towerW + 0.4, stoneDark, tx, towerCorniceY + 0.15, tz, "stone-ashlar"));

  // Dome drum (octagonal approximated by cylinder)
  const drumH = 1.5;
  const drumR = 1.6;
  towerGroup.add(makeCylinder(drumR, drumR, drumH, 8, stoneMat, tx, towerCorniceY + 0.3 + drumH / 2, tz, "stone-ashlar"));

  // Drum windows
  for (let a = 0; a < 4; a++) {
    const angle = (a / 4) * Math.PI * 2 + Math.PI / 4;
    const wx = tx + Math.cos(angle) * (drumR + 0.05);
    const wz = tz + Math.sin(angle) * (drumR + 0.05);
    const winGeo = new THREE.BoxGeometry(0.6, 0.9, 0.1);
    const win = new THREE.Mesh(winGeo, glassMat);
    win.userData.textureId = "glass-curtainwall";
    win.position.set(wx, towerCorniceY + 0.3 + drumH / 2, wz);
    win.lookAt(tx, towerCorniceY + 0.3 + drumH / 2, tz);
    win.rotateY(Math.PI);
    towerGroup.add(win);
  }

  // Dome
  const domeR = 1.7;
  const domeGeo = new THREE.SphereGeometry(domeR, 16, 12, 0, Math.PI * 2, 0, Math.PI / 2);
  const dome = new THREE.Mesh(domeGeo, roofMat);
  dome.userData.textureId = "roof-tiles";
  dome.position.set(tx, towerCorniceY + 0.3 + drumH, tz);
  towerGroup.add(dome);

  // Lantern on top
  const lanternY = towerCorniceY + 0.3 + drumH + domeR - 0.3;
  towerGroup.add(makeCylinder(0.3, 0.35, 1.0, 8, stoneMat, tx, lanternY + 0.5, tz, "stone-ashlar"));

  // Finial / spire
  towerGroup.add(makeCylinder(0.0, 0.15, 1.2, 8, goldMat, tx, lanternY + 1.6, tz, "stone-ashlar"));

  // Small dome on lantern
  const smallDomeGeo = new THREE.SphereGeometry(0.35, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2);
  const smallDome = new THREE.Mesh(smallDomeGeo, roofMat);
  smallDome.userData.textureId = "roof-tiles";
  smallDome.position.set(tx, lanternY + 1.0, tz);
  towerGroup.add(smallDome);

  return towerGroup;
}

