// ROOF - Hip roof with slate tiles
// ============================================
const roofBaseY = plinthHeight + totalWallHeight;
const roofOverhang = 1.2;
const roofW = buildingWidth + roofOverhang * 2;
const roofD = buildingDepth + roofOverhang * 2;

// Create hip roof using custom geometry
const roofGeo = new THREE.BufferGeometry();
const hw = roofW / 2;
const hd = roofD / 2;
const peakH = roofPeakHeight;

// Vertices for hip roof
// Base corners: 0-3, Peak ridge: 4-5 (for a hip roof with ridge along X)
const ridgeLength = (roofW - roofD) > 0 ? (roofW - roofD) / 2 : 0;

// For a roughly square building, use a pyramid hip roof
// Since width > depth, we have a short ridge
const vertices = new Float32Array([
  // Base corners
  -hw, 0, -hd,   // 0 front-left
   hw, 0, -hd,   // 1 front-right
   hw, 0,  hd,   // 2 back-right
  -hw, 0,  hd,   // 3 back-left
  // Ridge ends
  -ridgeLength, peakH, 0,  // 4 left peak
   ridgeLength, peakH, 0,  // 5 right peak
]);

const indices = [
  // Front face (triangle)
  0, 5, 1,
  0, 4, 5,
  // Back face
  2, 4, 3,
  2, 5, 4,
  // Left face (triangle)
  3, 4, 0,
  // Right face (triangle)
  1, 5, 2,
];

roofGeo.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
roofGeo.setIndex(indices);
roofGeo.computeVertexNormals();

const roofMat = new THREE.MeshStandardMaterial({ color: roofColor, side: THREE.DoubleSide });
const roof = new THREE.Mesh(roofGeo, roofMat);
roof.userData.textureId = "roof-tiles";
roof.position.set(0, roofBaseY, 0);
group.add(roof);

