// Main gable roof running left-right (ridge along X axis... actually looking at elevations, ridge runs along Z)
// From the front elevation: the roof slopes left and right with a dormer window
// From the side elevation: we see the gable end
// So the ridge runs front-to-back (along Z axis)

const roofGroup = new THREE.Group();
