function addBeam(x1, y1, z1, x2, y2, z2, thickness) {
  const t = thickness || 0.25;
  const dx = x2 - x1, dy = y2 - y1, dz = z2 - z1;
  const len = Math.sqrt(dx*dx + dy*dy + dz*dz);
  const geo = new THREE.BoxGeometry(t, t, len);
  const beam = new THREE.Mesh(geo, darkWoodMat);
  beam.position.set((x1+x2)/2, (y1+y2)/2, (z1+z2)/2);
  beam.lookAt(x2, y2, z2);
  beam.userData.textureId = "wood-siding";
  group.add(beam);
  return beam;
}

