addBeam(rX, 0, mainDepth/2, rX, wallHeight, mainDepth/2, 0.3);
addBeam(rX, 0, 0, rX, ridgeHeight, 0, 0.3);
// Horizontal beam
addBeam(rX, wallHeight, -mainDepth/2, rX, wallHeight, mainDepth/2, 0.3);
// Diagonal braces - gable
addBeam(rX, wallHeight, -mainDepth/2, rX, ridgeHeight, 0, 0.25);
addBeam(rX, wallHeight, mainDepth/2, rX, ridgeHeight, 0, 0.25);
// Knee braces
